#[derive(Debug, thiserror::Error)]
#[error("{0}")]
struct RetryableP2pRequestError(String);

fn retryable_p2p_request_failure(message: impl Into<String>) -> anyhow::Error {
    anyhow::Error::new(RetryableP2pRequestError(message.into()))
}

pub(crate) fn is_retryable_p2p_request_error(error: &anyhow::Error) -> bool {
    error.chain().any(|cause| {
        cause.downcast_ref::<RetryableP2pRequestError>().is_some()
            || cause
                .downcast_ref::<crate::WireError>()
                .is_some_and(|error| error.retryable)
    })
}

struct PolicyTransport<T> {
    inner: T,
    mode: TorMode,
}

impl<T> PolicyTransport<T> {
    fn new(inner: T, mode: TorMode) -> Self {
        Self { inner, mode }
    }
}

impl<T> Transport for PolicyTransport<T>
where
    T: Transport + Unpin,
{
    type Output = T::Output;
    type Error = T::Error;
    type ListenerUpgrade = T::ListenerUpgrade;
    type Dial = T::Dial;

    fn listen_on(
        &mut self,
        id: ListenerId,
        address: Multiaddr,
    ) -> std::result::Result<(), TransportError<Self::Error>> {
        if !transport_address_allowed(self.mode, &address) {
            return Err(TransportError::MultiaddrNotSupported(address));
        }
        self.inner.listen_on(id, address)
    }

    fn remove_listener(&mut self, id: ListenerId) -> bool {
        self.inner.remove_listener(id)
    }

    fn dial(
        &mut self,
        address: Multiaddr,
        options: TransportDialOpts,
    ) -> std::result::Result<Self::Dial, TransportError<Self::Error>> {
        if !transport_address_allowed(self.mode, &address) {
            return Err(TransportError::MultiaddrNotSupported(address));
        }
        self.inner.dial(address, options)
    }

    fn poll(
        mut self: Pin<&mut Self>,
        cx: &mut TaskContext<'_>,
    ) -> Poll<TransportEvent<Self::ListenerUpgrade, Self::Error>> {
        Pin::new(&mut self.inner).poll(cx)
    }
}

