    #[allow(dead_code)]
    pub(crate) async fn publish_parity(
        &self,
        peer: NodeId,
        group: CodingGroup,
        information: [Vec<u8>; 3],
        object: ParityObject,
    ) -> Result<SignedRecord<StorageAcknowledgement>> {
        let operation_id = storage_operation_id(&group.id, object.shard_index);
        let response = self
            .call(
                peer,
                PeerRequest::PublishParity {
                    operation_id,
                    group: Box::new(group),
                    information,
                    object,
                },
            )
            .await?;
        let PeerResponse::StorageAcknowledgement(acknowledgement) = response else {
            bail!("peer returned the wrong parity publication response");
        };
        acknowledgement.verify(STORAGE_ACKNOWLEDGEMENT_DOMAIN)?;
        acknowledgement.value.validate()?;
        if acknowledgement.value.operation_id != operation_id {
            bail!("parity acknowledgement has the wrong operation identity");
        }
        Ok(acknowledgement)
    }

    pub async fn stage_coding_parity(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        manifest: SignedRecord<CodingRootManifest>,
        object: VariableParityObject,
    ) -> Result<SignedRecord<StagedStorageReceipt>> {
        let expected_attempt = plan.value.attempt_id;
        let expected_group = manifest.value.group.id;
        let expected_index = object.shard_index;
        let expected_commitment = object.commitment.clone();
        // Full-byte manifests already carry substantial control evidence.
        // Send parity through the existing resumable range protocol so no
        // request also has to carry a complete parity shard.
        if plan.value.format_version == 3 {
            manifest.value.validate_for_plan(&plan.value)?;
            let Some(ShardRoleV2::Parity(parity)) =
                manifest.value.group.roles.get(usize::from(expected_index))
            else {
                bail!("parity staging object is not assigned to a parity role");
            };
            if object.format_version != 2
                || object.group_id != expected_group
                || object.guild_id != manifest.value.group.guild_id
                || parity.holder != peer
                || parity.commitment != expected_commitment
                || merkle_commit(&object.bytes)? != expected_commitment
            {
                bail!("parity staging object conflicts with its full-byte manifest");
            }
            let range_bytes = coding_parity_range_bytes(&plan, &manifest)?;
            let mut offset = self
                .reserve_coding_parity(peer, plan.clone(), expected_index)
                .await? as usize;
            while offset < object.bytes.len() {
                let end = offset.saturating_add(range_bytes).min(object.bytes.len());
                offset = self
                    .upload_coding_parity_range(
                        peer,
                        plan.clone(),
                        manifest.clone(),
                        expected_index,
                        offset as u32,
                        object.bytes[offset..end].to_vec(),
                    )
                    .await? as usize;
            }
            return self
                .finalize_coding_parity(peer, plan, manifest, expected_index)
                .await;
        }
        let response = self
            .call(
                peer,
                PeerRequest::StageCodingParity {
                    plan: Box::new(plan),
                    manifest: Box::new(manifest),
                    object,
                },
            )
            .await?;
        let PeerResponse::StagedStorageReceipt(receipt) = response else {
            bail!("peer returned the wrong staged parity response");
        };
        receipt.verify(STAGED_STORAGE_RECEIPT_DOMAIN)?;
        if receipt.signer != peer
            || receipt.value.holder != peer
            || receipt.value.attempt_id != expected_attempt
            || receipt.value.group_id != expected_group
            || receipt.value.shard_index != expected_index
            || receipt.value.commitment != expected_commitment
        {
            bail!("staged parity receipt conflicts with the coding plan");
        }
        Ok(receipt)
    }

    pub async fn reserve_coding_parity(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        shard_index: u16,
    ) -> Result<u32> {
        let shard_size = plan.value.geometry.profile.shard_size;
        let response = self
            .call(
                peer,
                PeerRequest::ReserveCodingParity {
                    plan: Box::new(plan),
                    shard_index,
                },
            )
            .await?;
        let PeerResponse::CodingRangeProgress { written_until } = response else {
            bail!("peer returned the wrong coding-reservation response");
        };
        if written_until > shard_size || !written_until.is_multiple_of(MERKLE_LEAF_SIZE as u32) {
            bail!("peer returned invalid coding-reservation progress");
        }
        Ok(written_until)
    }

    pub async fn reserve_coding_information(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        shard_index: u16,
    ) -> Result<u32> {
        let shard_size = plan.value.geometry.profile.shard_size;
        let response = self
            .call(
                peer,
                PeerRequest::ReserveCodingInformation {
                    plan: Box::new(plan),
                    shard_index,
                },
            )
            .await?;
        let PeerResponse::CodingRangeProgress { written_until } = response else {
            bail!("peer returned the wrong information-reservation response");
        };
        if written_until > shard_size || !written_until.is_multiple_of(MERKLE_LEAF_SIZE as u32) {
            bail!("peer returned invalid information-reservation progress");
        }
        Ok(written_until)
    }

    pub async fn upload_coding_information_range(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        shard_index: u16,
        offset: u32,
        bytes: Vec<u8>,
    ) -> Result<u32> {
        let expected = offset
            .checked_add(u32::try_from(bytes.len()).context("coding range is too large")?)
            .context("coding range offset overflow")?;
        let response = self
            .call(
                peer,
                PeerRequest::UploadCodingInformationRange {
                    plan: Box::new(plan),
                    shard_index,
                    offset,
                    bytes,
                },
            )
            .await?;
        let PeerResponse::CodingRangeProgress { written_until } = response else {
            bail!("peer returned the wrong information-upload response");
        };
        if written_until != expected {
            bail!("peer did not durably commit the complete information range");
        }
        Ok(written_until)
    }

    pub async fn finalize_coding_information(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        shard_index: u16,
    ) -> Result<()> {
        let response = self
            .call(
                peer,
                PeerRequest::FinalizeCodingInformation {
                    plan: Box::new(plan),
                    shard_index,
                },
            )
            .await?;
        if !matches!(response, PeerResponse::Ack) {
            bail!("peer returned the wrong information-finalization response");
        }
        Ok(())
    }

    pub async fn coding_information_range(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        shard_index: u16,
        start_leaf: u32,
        leaf_count: u32,
    ) -> Result<mb_core::MerkleRangeProof> {
        let commitment = plan
            .value
            .geometry
            .information
            .get(usize::from(shard_index))
            .context("coding information index is outside its plan")?
            .sector
            .commitment
            .clone();
        let response = self
            .call(
                peer,
                PeerRequest::GetCodingInformationRange {
                    plan: Box::new(plan),
                    shard_index,
                    start_leaf,
                    leaf_count,
                },
            )
            .await?;
        let PeerResponse::MerkleRange(proof) = response else {
            bail!("peer returned the wrong coding information range response");
        };
        if proof.start_leaf != start_leaf || proof.leaves.len() != leaf_count as usize {
            bail!("peer returned a different coding information range");
        }
        mb_core::merkle_verify_range(&commitment, &proof)?;
        Ok(proof)
    }

    #[allow(clippy::too_many_arguments)]
    pub async fn upload_coding_parity_range(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        manifest: SignedRecord<CodingRootManifest>,
        shard_index: u16,
        offset: u32,
        bytes: Vec<u8>,
    ) -> Result<u32> {
        let expected = offset
            .checked_add(u32::try_from(bytes.len()).context("coding range is too large")?)
            .context("coding range offset overflow")?;
        let response = self
            .call(
                peer,
                PeerRequest::UploadCodingParityRange {
                    plan: Box::new(plan),
                    manifest: Box::new(manifest),
                    shard_index,
                    offset,
                    bytes,
                },
            )
            .await?;
        let PeerResponse::CodingRangeProgress { written_until } = response else {
            bail!("peer returned the wrong coding-upload response");
        };
        if written_until != expected {
            bail!("peer did not durably commit the complete coding range");
        }
        Ok(written_until)
    }

    pub async fn finalize_coding_parity(
        &self,
        peer: NodeId,
        plan: SignedRecord<CodingAttemptPlan>,
        manifest: SignedRecord<CodingRootManifest>,
        shard_index: u16,
    ) -> Result<SignedRecord<StagedStorageReceipt>> {
        let attempt_id = plan.value.attempt_id;
        let plan_hash = plan.value.hash()?;
        let group_id = manifest.value.group.id;
        let response = self
            .call(
                peer,
                PeerRequest::FinalizeCodingParity {
                    plan: Box::new(plan),
                    manifest: Box::new(manifest),
                    shard_index,
                },
            )
            .await?;
        let PeerResponse::StagedStorageReceipt(receipt) = response else {
            bail!("peer returned the wrong coding-finalization response");
        };
        receipt.verify(STAGED_STORAGE_RECEIPT_DOMAIN)?;
        if receipt.signer != peer
            || receipt.value.holder != peer
            || receipt.value.attempt_id != attempt_id
            || receipt.value.plan_hash != plan_hash
            || receipt.value.group_id != group_id
            || receipt.value.shard_index != shard_index
        {
            bail!("staged parity receipt conflicts with the coding upload");
        }
        Ok(receipt)
    }

