    #[tokio::test]
    async fn prefer_tor_dispatches_on_tor_while_each_reservation_role_retains_direct_fallback() {
        let temp = tempfile::tempdir().unwrap();
        for (index, client_reservation) in [true, false].into_iter().enumerate() {
            let local_seed = Seed::from_bytes([120 + index as u8; 32]);
            let local_id = KeyMaterial::from_seed(&local_seed).node_id();
            let node = Arc::new(Mutex::new(
                Node::open(temp.path().join(index.to_string()), local_seed).unwrap(),
            ));
            let (client, mut event_loop) = build_p2p(node, config(local_id)).unwrap();
            event_loop.tor_mode = TorMode::PreferTor;
            let target =
                KeyMaterial::from_seed(&Seed::from_bytes([130 + index as u8; 32])).node_id();
            let peer = target.libp2p_peer_id().unwrap();
            let direct_address: Multiaddr =
                format!("/ip4/192.0.2.120/udp/44000/quic-v1/p2p/{peer}")
                    .parse()
                    .unwrap();
            let onion_address = onion_listener_address(target).unwrap();
            for address in [direct_address.clone(), onion_address.clone()] {
                event_loop.add_learned_address(peer, address).unwrap();
            }
            event_loop.set_transport_tier(peer, 0);

            let direct = ConnectionId::new_unchecked(1201 + index * 10);
            let tor = ConnectionId::new_unchecked(1202 + index * 10);
            for (connection, path) in [(direct, P2pPath::Direct), (tor, P2pPath::Tor)] {
                event_loop.connection_paths.insert(connection, (peer, path));
                event_loop.connection_dialers.insert(connection, true);
                event_loop.record_session_open(
                    connection,
                    peer,
                    path,
                    P2pSessionDirection::Outbound,
                );
                register_request_connection(&mut event_loop, peer, connection);
            }
            event_loop.protect_relay_reservation_connection(peer, direct, client_reservation);

            let call = tokio::spawn({
                let client = client.clone();
                async move { client.call(target, PeerRequest::Profile).await }
            });
            let command = event_loop.commands.recv().await.unwrap();
            event_loop.handle_command(command).unwrap();
            assert_eq!(next_request_dispatch(&mut event_loop).await, tor);
            let request_id = *event_loop.pending_requests.keys().next().unwrap();

            event_loop.handle_peer_event(request_response::Event::OutboundFailure {
                peer,
                connection_id: tor,
                request_id,
                error: request_response::OutboundFailure::ConnectionClosed,
            });
            assert_eq!(event_loop.selected_transport_tier(peer), 1);
            assert_eq!(next_request_dispatch(&mut event_loop).await, direct);
            assert_eq!(event_loop.pending_requests.len(), 1);
            assert!(event_loop.queued_requests.is_empty());
            event_loop.handle_swarm_event(SwarmEvent::ConnectionClosed {
                peer_id: peer,
                connection_id: tor,
                endpoint: ConnectedPoint::Dialer {
                    address: onion_address,
                    role_override: Endpoint::Dialer,
                    port_use: PortUse::Reuse,
                },
                num_established: 1,
                cause: None,
            });
            assert_eq!(event_loop.pending_requests.len(), 1);
            assert!(event_loop.queued_requests.is_empty());
            assert!(event_loop.connection_owns_relay_reservation(direct));

            drop(event_loop);
            assert!(call.await.unwrap().is_err());
        }
    }

    #[tokio::test]
    async fn fallback_dials_advance_in_order_despite_a_retained_worse_connection() {
        let temp = tempfile::tempdir().unwrap();
        let local_seed = Seed::from_bytes([92; 32]);
        let local_id = KeyMaterial::from_seed(&local_seed).node_id();
        let node = Arc::new(Mutex::new(Node::open(temp.path(), local_seed).unwrap()));
        let (client, mut event_loop) = build_p2p(node, config(local_id)).unwrap();
        event_loop.tor_mode = TorMode::Auto;
        let target = KeyMaterial::from_seed(&Seed::from_bytes([93; 32])).node_id();
        let peer = target.libp2p_peer_id().unwrap();
        let relay = KeyMaterial::from_seed(&Seed::from_bytes([94; 32]))
            .node_id()
            .libp2p_peer_id()
            .unwrap();
        let direct: Multiaddr = format!("/ip4/192.0.2.92/udp/44000/quic-v1/p2p/{peer}")
            .parse()
            .unwrap();
        let relayed: Multiaddr =
            format!("/ip4/192.0.2.93/udp/44001/quic-v1/p2p/{relay}/p2p-circuit/p2p/{peer}")
                .parse()
                .unwrap();
        for address in [direct, relayed, onion_listener_address(target).unwrap()] {
            event_loop.add_learned_address(peer, address).unwrap();
        }
        let tor_connection = ConnectionId::new_unchecked(921);
        event_loop
            .connection_paths
            .insert(tor_connection, (peer, P2pPath::Tor));
        register_request_connection(&mut event_loop, peer, tor_connection);

        let call = tokio::spawn({
            let client = client.clone();
            async move { client.call(target, PeerRequest::Profile).await }
        });
        let command = event_loop.commands.recv().await.unwrap();
        event_loop.handle_command(command).unwrap();
        assert_eq!(event_loop.queued_requests.len(), 1);
        let direct_dial = event_loop
            .policy_dials
            .iter()
            .find_map(|(connection, dial)| {
                (dial.peer == peer && dial.tier == 0).then_some(*connection)
            })
            .unwrap();

        event_loop.handle_swarm_event(SwarmEvent::OutgoingConnectionError {
            connection_id: direct_dial,
            peer_id: Some(peer),
            error: libp2p::swarm::DialError::Aborted,
        });
        assert_eq!(event_loop.selected_transport_tier(peer), 1);
        assert_eq!(event_loop.queued_requests.len(), 1);
        let relay_dial = event_loop
            .policy_dials
            .iter()
            .find_map(|(connection, dial)| {
                (dial.peer == peer && dial.tier == 1).then_some(*connection)
            })
            .unwrap();

        let stale_direct_dial = ConnectionId::new_unchecked(922);
        event_loop.policy_dials.insert(
            stale_direct_dial,
            PolicyDial {
                peer,
                tier: 0,
                path: P2pPath::Direct,
                kind: PolicyDialKind::Selected,
                addresses: BTreeSet::new(),
                superseded: false,
            },
        );
        event_loop.handle_swarm_event(SwarmEvent::OutgoingConnectionError {
            connection_id: stale_direct_dial,
            peer_id: Some(peer),
            error: libp2p::swarm::DialError::Aborted,
        });
        assert_eq!(event_loop.selected_transport_tier(peer), 1);
        assert!(event_loop.policy_dials.contains_key(&relay_dial));

        event_loop.handle_swarm_event(SwarmEvent::OutgoingConnectionError {
            connection_id: relay_dial,
            peer_id: Some(peer),
            error: libp2p::swarm::DialError::Aborted,
        });
        assert_eq!(event_loop.selected_transport_tier(peer), 2);
        assert!(event_loop.queued_requests.is_empty());
        assert_eq!(event_loop.pending_requests.len(), 1);

        drop(event_loop);
        assert!(call.await.unwrap().is_err());
    }

    #[tokio::test]
    async fn final_fallback_dial_failure_uses_an_established_preferred_probe() {
        let temp = tempfile::tempdir().unwrap();
        let local_seed = Seed::from_bytes([113; 32]);
        let local_id = KeyMaterial::from_seed(&local_seed).node_id();
        let node = Arc::new(Mutex::new(Node::open(temp.path(), local_seed).unwrap()));
        let (client, mut event_loop) = build_p2p(node, config(local_id)).unwrap();
        event_loop.tor_mode = TorMode::Auto;
        let target = KeyMaterial::from_seed(&Seed::from_bytes([114; 32])).node_id();
        let peer = target.libp2p_peer_id().unwrap();
        for address in [
            format!("/ip4/192.0.2.113/udp/44000/quic-v1/p2p/{peer}")
                .parse()
                .unwrap(),
            onion_listener_address(target).unwrap(),
        ] {
            event_loop.add_learned_address(peer, address).unwrap();
        }
        event_loop.set_transport_tier(peer, 2);

        let call = tokio::spawn({
            let client = client.clone();
            async move { client.call(target, PeerRequest::Profile).await }
        });
        let command = event_loop.commands.recv().await.unwrap();
        event_loop.handle_command(command).unwrap();
        assert_eq!(event_loop.queued_requests.len(), 1);
        let signed_request =
            canonical_bytes(&event_loop.queued_requests.front().unwrap().request).unwrap();
        let tor_dial = event_loop
            .policy_dials
            .iter()
            .find_map(|(connection, dial)| {
                (dial.peer == peer && dial.tier == 2 && dial.kind == PolicyDialKind::Selected)
                    .then_some(*connection)
            })
            .unwrap();

        let direct = ConnectionId::new_unchecked(814);
        event_loop
            .connection_paths
            .insert(direct, (peer, P2pPath::Direct));
        register_request_connection(&mut event_loop, peer, direct);
        event_loop.observe_established_transport(peer, direct);
        event_loop.drain_queued_requests(peer);
        assert_eq!(event_loop.selected_transport_tier(peer), 2);
        assert_eq!(event_loop.transport_promotions[&peer].tier, 0);
        assert_eq!(event_loop.queued_requests.len(), 1);
        assert!(!call.is_finished());

        event_loop.handle_swarm_event(SwarmEvent::OutgoingConnectionError {
            connection_id: tor_dial,
            peer_id: Some(peer),
            error: libp2p::swarm::DialError::Aborted,
        });

        assert_eq!(event_loop.selected_transport_tier(peer), 0);
        assert!(!event_loop.transport_promotions.contains_key(&peer));
        assert!(event_loop.queued_requests.is_empty());
        assert_eq!(next_request_dispatch(&mut event_loop).await, direct);
        let outbound = *event_loop.pending_requests.keys().next().unwrap();
        assert_eq!(
            canonical_bytes(&event_loop.pending_requests[&outbound].request).unwrap(),
            signed_request
        );
        let mut completed = event_loop.pending_requests.remove(&outbound).unwrap();
        completed.finish(Ok(PeerResponse::Ack));
        assert!(matches!(call.await.unwrap().unwrap(), PeerResponse::Ack));
    }

