    #[tokio::test]
    async fn learned_endpoint_cache_replaces_and_expires_addresses() {
        let temp = tempfile::tempdir().unwrap();
        let node = Node::open(temp.path(), Seed::from_bytes([73; 32])).unwrap();
        let local_id = node.keys().node_id();
        let (_client, mut event_loop) =
            build_p2p(Arc::new(Mutex::new(node)), config(local_id)).unwrap();
        event_loop.tor_mode = TorMode::PreferTor;
        let peer = mb_core::KeyMaterial::from_seed(&Seed::from_bytes([72; 32]))
            .node_id()
            .libp2p_peer_id()
            .unwrap();
        let first: Multiaddr = format!("/ip4/127.0.0.1/udp/4101/quic-v1/p2p/{peer}")
            .parse()
            .unwrap();
        let second: Multiaddr = format!("/ip4/127.0.0.1/udp/4102/quic-v1/p2p/{peer}")
            .parse()
            .unwrap();

        event_loop.add_learned_address(peer, first.clone()).unwrap();
        assert_eq!(event_loop.fallback_tiers.get(&peer), Some(&1));
        assert!(!event_loop.persistent_addresses.contains_key(&peer));
        assert_eq!(event_loop.learned_addresses[&peer].addresses.len(), 1);
        event_loop
            .replace_learned_addresses(peer, vec![first.clone()], unix_seconds() + 300)
            .unwrap();
        assert_eq!(event_loop.learned_addresses[&peer].addresses.len(), 1);
        event_loop.record_transfer(peer, Some(P2pPath::Direct), 10, 20);
        assert!(event_loop.transfer_counters.contains_key(&peer));
        assert!(event_loop.path_transfer_counters.contains_key(&peer));
        event_loop
            .replace_learned_addresses(peer, vec![second.clone()], unix_seconds() + 300)
            .unwrap();
        assert_eq!(
            event_loop.learned_addresses[&peer]
                .addresses
                .iter()
                .next()
                .unwrap()
                .to_string(),
            "/ip4/127.0.0.1/udp/4102/quic-v1"
        );
        event_loop.add_learned_address(peer, first.clone()).unwrap();
        event_loop
            .add_identified_address(peer, first.clone())
            .unwrap();
        assert_eq!(
            event_loop.retained_peer_addresses(peer),
            BTreeSet::from([normalize_known_address(peer, second).unwrap()])
        );
        event_loop
            .replace_learned_addresses(peer, Vec::new(), unix_seconds() + 300)
            .unwrap();
        event_loop.add_learned_address(peer, first.clone()).unwrap();
        event_loop
            .add_identified_address(peer, first.clone())
            .unwrap();
        assert!(event_loop.retained_peer_addresses(peer).is_empty());

        event_loop
            .learned_addresses
            .get_mut(&peer)
            .unwrap()
            .expires_at = tokio::time::Instant::now();
        event_loop.expire_learned_addresses();
        assert!(!event_loop.learned_addresses.contains_key(&peer));
        assert!(!event_loop.fallback_tiers.contains_key(&peer));
        assert!(!event_loop.transfer_counters.contains_key(&peer));
        assert!(!event_loop.path_transfer_counters.contains_key(&peer));
        event_loop.add_learned_address(peer, first).unwrap();
        assert_eq!(event_loop.learned_addresses[&peer].addresses.len(), 1);
        event_loop.learned_addresses.remove(&peer);
        event_loop.reconcile_policy_addresses(peer);

        for port in 4200..4200 + MAX_ENDPOINTS_PER_PEER {
            let address = format!("/ip4/127.0.0.1/udp/{port}/quic-v1/p2p/{peer}")
                .parse()
                .unwrap();
            event_loop.add_learned_address(peer, address).unwrap();
        }
        let excess = format!("/ip4/127.0.0.1/udp/4300/quic-v1/p2p/{peer}")
            .parse()
            .unwrap();
        assert!(event_loop.add_learned_address(peer, excess).is_err());
        assert_eq!(
            event_loop.learned_addresses[&peer].addresses.len(),
            MAX_ENDPOINTS_PER_PEER
        );
    }

    #[tokio::test]
    async fn signed_relay_endpoint_cannot_be_displaced_by_stale_direct_hints() {
        let temp = tempfile::tempdir().unwrap();
        let node = Node::open(temp.path(), Seed::from_bytes([73; 32])).unwrap();
        let local_id = node.keys().node_id();
        let (_client, mut event_loop) =
            build_p2p(Arc::new(Mutex::new(node)), config(local_id)).unwrap();
        let peer = KeyMaterial::from_seed(&Seed::from_bytes([72; 32]))
            .node_id()
            .libp2p_peer_id()
            .unwrap();
        let relay = KeyMaterial::from_seed(&Seed::from_bytes([71; 32]))
            .node_id()
            .libp2p_peer_id()
            .unwrap();
        let old_direct: Multiaddr = "/ip4/127.0.0.1/udp/4101/quic-v1".parse().unwrap();
        let current_relay: Multiaddr =
            format!("/ip4/198.18.0.2/udp/4102/quic-v1/p2p/{relay}/p2p-circuit/p2p/{peer}")
                .parse()
                .unwrap();

        event_loop
            .persistent_addresses
            .insert(peer, BTreeSet::from([old_direct.clone()]));
        event_loop
            .add_recovery_addresses(
                Uuid::new_v4(),
                peer,
                vec![old_direct.clone()],
                unix_seconds() + 300,
            )
            .unwrap();
        event_loop
            .add_learned_address(peer, old_direct.clone())
            .unwrap();
        assert_eq!(event_loop.selected_path_hint(peer), Some(P2pPath::Direct));
        let direct_tier = path_preference_rank(event_loop.tor_mode, P2pPath::Direct);
        let relay_tier = path_preference_rank(event_loop.tor_mode, P2pPath::Relayed);
        assert!(event_loop.start_policy_dial(
            peer,
            direct_tier,
            vec![old_direct.clone()],
            PolicyDialKind::Selected,
        ));
        event_loop
            .replace_learned_addresses(peer, vec![current_relay.clone()], unix_seconds() + 300)
            .unwrap();
        assert!(
            event_loop
                .policy_dials
                .values()
                .any(|dial| dial.peer == peer && dial.tier == direct_tier && dial.superseded)
        );
        assert!(!event_loop.policy_dial_exists(peer, direct_tier));
        assert_eq!(event_loop.selected_transport_tier(peer), relay_tier);
        event_loop.ensure_selected_transport(peer);
        assert!(event_loop.policy_dial_exists(peer, relay_tier));
        event_loop
            .add_learned_address(peer, old_direct.clone())
            .unwrap();
        event_loop.add_identified_address(peer, old_direct).unwrap();

        assert_eq!(event_loop.selected_path_hint(peer), Some(P2pPath::Relayed));
        assert_eq!(
            event_loop.retained_peer_addresses(peer),
            BTreeSet::from([normalize_known_address(peer, current_relay).unwrap()])
        );
        event_loop
            .replace_learned_addresses(peer, Vec::new(), unix_seconds() + 300)
            .unwrap();
        assert!(event_loop.retained_peer_addresses(peer).is_empty());
    }

    #[tokio::test]
    async fn signed_same_tier_replacement_dials_before_obsolete_attempt_finishes() {
        let temp = tempfile::tempdir().unwrap();
        let node = Node::open(temp.path(), Seed::from_bytes([79; 32])).unwrap();
        let local_id = node.keys().node_id();
        let (_client, mut event_loop) =
            build_p2p(Arc::new(Mutex::new(node)), config(local_id)).unwrap();
        let peer = KeyMaterial::from_seed(&Seed::from_bytes([80; 32]))
            .node_id()
            .libp2p_peer_id()
            .unwrap();
        let old: Multiaddr = "/ip4/127.0.0.1/udp/4401/quic-v1".parse().unwrap();
        let replacement: Multiaddr = "/ip4/127.0.0.1/udp/4402/quic-v1".parse().unwrap();
        event_loop
            .replace_learned_addresses(peer, vec![old.clone()], unix_seconds() + 300)
            .unwrap();
        let tier = path_preference_rank(event_loop.tor_mode, P2pPath::Direct);
        assert!(event_loop.start_policy_dial(
            peer,
            tier,
            vec![normalize_known_address(peer, old).unwrap()],
            PolicyDialKind::Selected,
        ));
        let old_dial = *event_loop.policy_dials.keys().next().unwrap();
        event_loop
            .replace_learned_addresses(peer, vec![replacement.clone()], unix_seconds() + 300)
            .unwrap();
        assert!(event_loop.policy_dials[&old_dial].superseded);
        assert!(!event_loop.policy_dial_exists(peer, tier));
        event_loop.ensure_selected_transport(peer);
        assert!(event_loop.policy_dials.iter().any(|(id, dial)| {
            *id != old_dial
                && dial.peer == peer
                && dial.tier == tier
                && !dial.superseded
                && dial.addresses
                    == BTreeSet::from([normalize_known_address(peer, replacement.clone()).unwrap()])
        }));
        event_loop.handle_swarm_event(SwarmEvent::OutgoingConnectionError {
            connection_id: old_dial,
            peer_id: Some(peer),
            error: libp2p::swarm::DialError::Aborted,
        });
        assert_eq!(event_loop.selected_transport_tier(peer), tier);
        assert!(event_loop.policy_dial_exists(peer, tier));
    }

