    #[tokio::test]
    async fn removed_offline_holder_cleanup_retries_after_reopen() {
        let temp = tempfile::tempdir().unwrap();
        let seeds = (201_u8..206)
            .map(|byte| Seed::from_bytes([byte; 32]))
            .collect::<Vec<_>>();
        let nodes = seeds
            .iter()
            .enumerate()
            .map(|(index, seed)| {
                Arc::new(Mutex::new(
                    Node::open(temp.path().join(format!("node-{index}")), seed.clone()).unwrap(),
                ))
            })
            .collect::<Vec<_>>();
        let mut clients = Vec::new();
        let mut tasks = Vec::new();
        for (index, node) in nodes.iter().enumerate() {
            let volume = temp.path().join(format!("volume-{index}"));
            std::fs::create_dir(&volume).unwrap();
            node.lock()
                .unwrap()
                .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                .unwrap();
            let mut cfg = config(node.lock().unwrap().keys().node_id());
            cfg.enable_relay_server = false;
            let (client, event_loop) = build_p2p(node.clone(), cfg).unwrap();
            clients.push(client);
            tasks.push(tokio::spawn(event_loop.run()));
        }
        let addresses = futures::future::join_all(clients.iter().map(listening_address)).await;
        let endpoints = clients
            .iter()
            .zip(addresses.iter().cloned())
            .map(|(client, address)| peer_endpoint(client, address))
            .collect::<Vec<_>>();
        form_test_guild(&nodes, &clients, &addresses, &endpoints).await;
        let ids = nodes
            .iter()
            .map(|node| node.lock().unwrap().keys().node_id())
            .collect::<Vec<_>>();
        let state = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let member = |id| {
            state
                .active_members()
                .find(|member| member.node_id == id)
                .unwrap()
                .clone()
        };
        let bytes = vec![67; 64];
        let plan = nodes[0]
            .lock()
            .unwrap()
            .sign_coding_attempt_plan(CodingAttemptPlan {
                format_version: 3,
                attempt_id: [73; 16],
                checkpoint_hash: [74; 32],
                membership_epoch: state.membership_epoch,
                geometry: CodingPlanGeometry {
                    format_version: 1,
                    guild_id: state.guild_id,
                    profile: CodingProfile::new(1, 1, 64),
                    information: vec![InformationRoleV2 {
                        owner: ids[0],
                        failure_domain: member(ids[0]).failure_domain,
                        sector: RangeSectorRef {
                            id: [75; 32],
                            commitment: merkle_commit(&bytes).unwrap(),
                            logical_len: 64,
                            virtual_zero: false,
                        },
                    }],
                    parity: vec![ParityPlacementV2 {
                        holder: ids[1],
                        failure_domain: member(ids[1]).failure_domain,
                        row: 0,
                    }],
                },
                delegator: ids[0],
                coding_coordinator: ids[2],
                verification_coordinator: ids[3],
                expires_at_unix_seconds: unix_seconds() + 600,
                information_roots: Some(vec![sector_root(&bytes)]),
            })
            .unwrap();
        let mut reserved_value = plan.value.clone();
        reserved_value.attempt_id = [76; 16];
        let reserved = nodes[0]
            .lock()
            .unwrap()
            .sign_coding_attempt_plan(reserved_value)
            .unwrap();
        let (manifest, parity) = nodes[2]
            .lock()
            .unwrap()
            .encode_delegated_coding(&plan, vec![Some(bytes)])
            .unwrap();
        let ShardRoleV2::Parity(role) = &manifest.value.group.roles[1] else {
            unreachable!();
        };
        nodes[1]
            .lock()
            .unwrap()
            .stage_coding_parity(
                &plan,
                &manifest,
                &VariableParityObject {
                    format_version: 2,
                    guild_id: state.guild_id,
                    group_id: manifest.value.group.id,
                    shard_index: 1,
                    commitment: role.commitment.clone(),
                    bytes: parity[0].clone(),
                },
            )
            .unwrap();
        nodes[1]
            .lock()
            .unwrap()
            .reserve_coding_parity(&reserved, 1)
            .unwrap();
        {
            let holder = nodes[1].lock().unwrap();
            assert!(holder.coding_used_bytes_for_test().unwrap() > 0);
            assert_eq!(holder.coding_staged_receipt_count_for_test().unwrap(), 1);
            assert_eq!(holder.coding_reservation_count_for_test().unwrap(), 1);
        }

        // A fenced failed attempt can transfer progress while an active
        // holder is offline, provided its cleanup obligation stays durable.
        clients[1].shutdown().await.unwrap();
        tasks.remove(1).await.unwrap().unwrap();
        assert!(
            nodes[0]
                .lock()
                .unwrap()
                .retire_coding_retry_plan(&plan)
                .unwrap()
        );
        abort_fenced_delegated_coding(
            nodes[0].clone(),
            &clients[0],
            &DelegatedCodingJob {
                format_version: 1,
                plan: plan.clone(),
                state: DelegatedCodingJobState::Cleanup,
                transcript: None,
                error: None,
            },
        )
        .await
        .unwrap();
        assert_eq!(
            nodes[0]
                .lock()
                .unwrap()
                .coding_holder_cleanup_count_for_test()
                .unwrap(),
            1
        );

        // The holder misses the removal event while its network is offline.
        let event = GuildEvent {
            format_version: 1,
            guild_id: state.guild_id,
            sequence: state.event_sequence + 1,
            parent: state.event_head,
            kind: mb_core::GuildEventKind::RemoveMember { node_id: ids[1] },
        };
        let mut signatures = nodes
            .iter()
            .map(|node| mb_core::sign_guild_event(&event, node.lock().unwrap().keys()).unwrap())
            .collect::<Vec<_>>();
        signatures.sort_by_key(|signature| signature.signer);
        let certified = QuorumGuildEvent { event, signatures };
        for (index, node) in nodes.iter().enumerate() {
            if index != 1 {
                node.lock()
                    .unwrap()
                    .install_guild_event(certified.clone())
                    .unwrap();
            }
        }
        for pending in [&plan, &reserved] {
            abort_stale_delegated_coding(
                nodes[0].clone(),
                &clients[0],
                &DelegatedCodingJob {
                    format_version: 1,
                    plan: pending.clone(),
                    state: DelegatedCodingJobState::Cleanup,
                    transcript: None,
                    error: None,
                },
            )
            .await
            .unwrap();
        }
        assert_eq!(
            nodes[0]
                .lock()
                .unwrap()
                .coding_holder_cleanup_count_for_test()
                .unwrap(),
            2
        );
        for (index, client) in clients.iter().enumerate() {
            if index != 1 {
                client.shutdown().await.unwrap();
            }
        }
        for task in tasks {
            task.await.unwrap().unwrap();
        }
        drop(clients);
        drop(nodes);

        for _ in 0..2 {
            let owner = Node::open(temp.path().join("node-0"), seeds[0].clone()).unwrap();
            let holder = Node::open(temp.path().join("node-1"), seeds[1].clone()).unwrap();
            assert_eq!(owner.coding_holder_cleanup_count_for_test().unwrap(), 2);
            assert!(holder.coding_used_bytes_for_test().unwrap() > 0);
            assert_eq!(holder.coding_staged_receipt_count_for_test().unwrap(), 1);
            assert_eq!(holder.coding_reservation_count_for_test().unwrap(), 1);
        }

        let owner = Arc::new(Mutex::new(
            Node::open(temp.path().join("node-0"), seeds[0].clone()).unwrap(),
        ));
        let holder = Arc::new(Mutex::new(
            Node::open(temp.path().join("node-1"), seeds[1].clone()).unwrap(),
        ));
        holder
            .lock()
            .unwrap()
            .install_guild_event(certified.clone())
            .unwrap();
        let seed_node = Arc::new(Mutex::new(
            Node::open(temp.path().join("node-2"), seeds[2].clone()).unwrap(),
        ));
        let mut owner_cfg = config(ids[0]);
        owner_cfg.enable_relay_server = false;
        let mut holder_cfg = config(ids[1]);
        holder_cfg.enable_relay_server = false;
        let mut seed_cfg = config(ids[2]);
        seed_cfg.enable_relay_server = false;
        let (owner_client, owner_event) = build_p2p(owner.clone(), owner_cfg).unwrap();
        let (holder_client, holder_event) = build_p2p(holder.clone(), holder_cfg).unwrap();
        let (seed_client, seed_event) = build_p2p(seed_node.clone(), seed_cfg).unwrap();
        let owner_task = tokio::spawn(owner_event.run());
        let holder_task = tokio::spawn(holder_event.run());
        let seed_task = tokio::spawn(seed_event.run());
        let holder_address = listening_address(&holder_client).await;
        assert_ne!(holder_address, addresses[1]);
        let seed_address = listening_address(&seed_client).await;
        owner_client
            .add_peer_address(ids[2], seed_address.clone())
            .await
            .unwrap();
        holder_client
            .add_peer_address(ids[2], seed_address)
            .await
            .unwrap();
        owner_client.profile(ids[2]).await.unwrap();
        holder_client.profile(ids[2]).await.unwrap();
        publish_dht_once(holder.clone(), &holder_client)
            .await
            .unwrap();
        let mut cursor = None;
        for _ in 0..8 {
            process_coding_holder_cleanup_job(owner.clone(), &owner_client, &mut cursor)
                .await
                .unwrap();
            if owner
                .lock()
                .unwrap()
                .coding_holder_cleanup_count_for_test()
                .unwrap()
                == 0
            {
                break;
            }
        }
        assert_eq!(
            owner
                .lock()
                .unwrap()
                .coding_holder_cleanup_count_for_test()
                .unwrap(),
            0
        );
        {
            let holder = holder.lock().unwrap();
            assert_eq!(holder.coding_used_bytes_for_test().unwrap(), 0);
            assert_eq!(holder.coding_staged_receipt_count_for_test().unwrap(), 0);
            assert_eq!(holder.coding_reservation_count_for_test().unwrap(), 0);
        }
        owner_client.shutdown().await.unwrap();
        holder_client.shutdown().await.unwrap();
        seed_client.shutdown().await.unwrap();
        owner_task.await.unwrap().unwrap();
        holder_task.await.unwrap().unwrap();
        seed_task.await.unwrap().unwrap();
        drop(owner_client);
        drop(holder_client);
        drop(seed_client);
        drop(owner);
        drop(holder);
        drop(seed_node);
        for _ in 0..2 {
            let owner = Node::open(temp.path().join("node-0"), seeds[0].clone()).unwrap();
            let holder = Node::open(temp.path().join("node-1"), seeds[1].clone()).unwrap();
            assert_eq!(owner.coding_holder_cleanup_count_for_test().unwrap(), 0);
            assert_eq!(holder.coding_used_bytes_for_test().unwrap(), 0);
            assert_eq!(holder.coding_staged_receipt_count_for_test().unwrap(), 0);
            assert_eq!(holder.coding_reservation_count_for_test().unwrap(), 0);
        }
    }

    #[tokio::test]
    async fn negative_opening_activation_worker_requeues_retry_after_holder_abort() {
        let temp = tempfile::tempdir().unwrap();
        let (seed, certificate, peers) = crate::node::tests::recovery_guild_fixture();
        let keys = (0_u8..5)
            .map(|i| KeyMaterial::from_seed(&Seed::from_bytes([120 + i; 32])))
            .collect::<Vec<_>>();
        let owner_id = KeyMaterial::from_seed(&seed).node_id();
        let remotes = keys
            .iter()
            .filter(|key| key.node_id() != owner_id)
            .collect::<Vec<_>>();
        let holder_id = remotes[0].node_id();
        let holder_seed = (0_u8..5)
            .map(|i| Seed::from_bytes([120 + i; 32]))
            .find(|seed| KeyMaterial::from_seed(seed).node_id() == holder_id)
            .unwrap();
        let owner_path = temp.path().join("owner");
        let holder_path = temp.path().join("holder");
        let owner = Arc::new(Mutex::new(Node::open(&owner_path, seed.clone()).unwrap()));
        let holder = Arc::new(Mutex::new(
            Node::open(&holder_path, holder_seed.clone()).unwrap(),
        ));
        for node in [&owner, &holder] {
            node.lock()
                .unwrap()
                .adopt_recovered_guild(certificate.clone(), peers.clone())
                .unwrap();
        }
        let volume = temp.path().join("holder-volume");
        std::fs::create_dir(&volume).unwrap();
        holder
            .lock()
            .unwrap()
            .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
            .unwrap();
        let state = owner
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let member = |id| {
            state
                .active_members()
                .find(|member| member.node_id == id)
                .unwrap()
                .clone()
        };
        let shards = encode(CodingProfile::new(1, 1, 64), vec![vec![67; 64]]).unwrap();
        let initial = owner
            .lock()
            .unwrap()
            .sign_coding_attempt_plan(CodingAttemptPlan {
                format_version: 3,
                attempt_id: [73; 16],
                checkpoint_hash: [74; 32],
                membership_epoch: state.membership_epoch,
                geometry: CodingPlanGeometry {
                    format_version: 1,
                    guild_id: state.guild_id,
                    profile: CodingProfile::new(1, 1, 64),
                    information: vec![InformationRoleV2 {
                        owner: owner_id,
                        failure_domain: member(owner_id).failure_domain,
                        sector: RangeSectorRef {
                            id: [75; 32],
                            commitment: merkle_commit(&shards[0]).unwrap(),
                            logical_len: 64,
                            virtual_zero: false,
                        },
                    }],
                    parity: vec![ParityPlacementV2 {
                        holder: holder_id,
                        failure_domain: member(holder_id).failure_domain,
                        row: 0,
                    }],
                },
                delegator: owner_id,
                coding_coordinator: remotes[1].node_id(),
                verification_coordinator: remotes[2].node_id(),
                expires_at_unix_seconds: unix_seconds() + 600,
                information_roots: Some(vec![sector_root(&shards[0])]),
            })
            .unwrap();
        owner
            .lock()
            .unwrap()
            .enqueue_coding_launch_with_information(initial.clone(), Some(BTreeMap::new()))
            .unwrap();
        let failure = SignedRecord::sign(
            CODING_FAILURE_REPORT_DOMAIN,
            CodingFailureReport {
                format_version: 1,
                failed_at_unix_seconds: unix_seconds(),
                plan: initial.clone(),
                error_hash: [76; 32],
            },
            remotes[1],
        )
        .unwrap();
        owner
            .lock()
            .unwrap()
            .accept_coding_failure(initial.value.coding_coordinator, failure)
            .unwrap();
        let child = owner
            .lock()
            .unwrap()
            .prepare_coding_retry(
                initial.value.attempt_id,
                holder_id,
                remotes[3].node_id(),
                unix_seconds() + 600,
            )
            .unwrap();
        owner
            .lock()
            .unwrap()
            .complete_coding_retry(initial.value.attempt_id)
            .unwrap();
        let (manifest, parity) =
            mb_core::encode_coding_attempt(&child, vec![Some(shards[0].clone())], remotes[0])
                .unwrap();
        let ShardRoleV2::Parity(role) = &manifest.value.group.roles[1] else {
            unreachable!();
        };
        holder
            .lock()
            .unwrap()
            .stage_coding_parity(
                &child,
                &manifest,
                &VariableParityObject {
                    format_version: 2,
                    guild_id: state.guild_id,
                    group_id: manifest.value.group.id,
                    shard_index: 1,
                    commitment: role.commitment.clone(),
                    bytes: parity[0].clone(),
                },
            )
            .unwrap();
        assert!(holder.lock().unwrap().coding_used_bytes_for_test().unwrap() > 0);
        let mut negative =
            crate::node::tests::test_coding_transcript(child.clone(), &shards, &keys);
        negative.value.openings[1].value.proof.leaves[0][0] ^= 1;
        negative.value.openings[1] = SignedRecord::sign(
            CODING_SHARD_OPENING_DOMAIN,
            negative.value.openings[1].value.clone(),
            remotes[0],
        )
        .unwrap();
        negative = SignedRecord::sign(
            mb_core::CODING_TRANSCRIPT_DOMAIN,
            negative.value,
            remotes[3],
        )
        .unwrap();
        assert!(matches!(
            replay_coding_transcript(&negative).unwrap(),
            mb_core::CodingReplayFinding::InvalidOpening { holder, shard_index: 1 }
                if holder == holder_id
        ));
        owner
            .lock()
            .unwrap()
            .accept_coding_transcript(child.value.coding_coordinator, negative.clone())
            .unwrap();
        let mut owner_cfg = config(owner_id);
        owner_cfg.enable_relay_server = false;
        owner_cfg.configure_failure_domain = false;
        let mut holder_cfg = config(holder_id);
        holder_cfg.enable_relay_server = false;
        holder_cfg.configure_failure_domain = false;
        let (owner_client, owner_event) = build_p2p(owner.clone(), owner_cfg).unwrap();
        let (holder_client, holder_event) = build_p2p(holder.clone(), holder_cfg).unwrap();
        let owner_task = tokio::spawn(owner_event.run());
        let holder_task = tokio::spawn(holder_event.run());
        let holder_address = listening_address(&holder_client).await;
        owner_client
            .add_peer_address(holder_id, holder_address)
            .await
            .unwrap();
        process_coding_activation_job(owner.clone(), &owner_client)
            .await
            .unwrap();
        {
            let owner = owner.lock().unwrap();
            let parent = owner
                .coding_retry_evidence_for_test(initial.value.attempt_id)
                .unwrap();
            assert!(!parent.complete);
            assert!(parent.retry_plan.is_none());
            assert_eq!(owner.coding_retry_previous_plan(&parent).unwrap(), child);
            assert!(
                owner
                    .coding_launch_information_to_stage(initial.value.attempt_id)
                    .unwrap()
                    .is_some()
            );
            assert!(
                owner
                    .coding_checkpoint_has_pending(initial.value.checkpoint_hash)
                    .unwrap()
            );
            assert_eq!(
                owner.coding_activation_jobs_for_test().unwrap()[0].transcript,
                negative
            );
        }
        {
            let holder = holder.lock().unwrap();
            assert_eq!(holder.coding_used_bytes_for_test().unwrap(), 0);
            assert_eq!(holder.coding_staged_receipt_count_for_test().unwrap(), 0);
            assert_eq!(holder.coding_reservation_count_for_test().unwrap(), 0);
        }
        let mut first_value = initial.value.clone();
        first_value.attempt_id = [80; 16];
        first_value.checkpoint_hash = [81; 32];
        let first = owner
            .lock()
            .unwrap()
            .sign_coding_attempt_plan(first_value)
            .unwrap();
        owner
            .lock()
            .unwrap()
            .enqueue_coding_launch_with_information(first.clone(), Some(BTreeMap::new()))
            .unwrap();
        let (first_manifest, first_parity) =
            mb_core::encode_coding_attempt(&first, vec![Some(shards[0].clone())], remotes[1])
                .unwrap();
        let ShardRoleV2::Parity(first_role) = &first_manifest.value.group.roles[1] else {
            unreachable!();
        };
        holder
            .lock()
            .unwrap()
            .stage_coding_parity(
                &first,
                &first_manifest,
                &VariableParityObject {
                    format_version: 2,
                    guild_id: state.guild_id,
                    group_id: first_manifest.value.group.id,
                    shard_index: 1,
                    commitment: first_role.commitment.clone(),
                    bytes: first_parity[0].clone(),
                },
            )
            .unwrap();
        let mut first_negative =
            crate::node::tests::test_coding_transcript(first.clone(), &shards, &keys);
        first_negative.value.openings[1].value.proof.leaves[0][0] ^= 1;
        first_negative.value.openings[1] = SignedRecord::sign(
            CODING_SHARD_OPENING_DOMAIN,
            first_negative.value.openings[1].value.clone(),
            remotes[0],
        )
        .unwrap();
        first_negative = SignedRecord::sign(
            mb_core::CODING_TRANSCRIPT_DOMAIN,
            first_negative.value,
            remotes[2],
        )
        .unwrap();
        owner
            .lock()
            .unwrap()
            .accept_coding_transcript(first.value.coding_coordinator, first_negative)
            .unwrap();
        // The dispatched launch may be removed before activation cleanup;
        // its input still pins the first attempt's packed source.
        owner
            .lock()
            .unwrap()
            .abandon_coding_launch(first.value.attempt_id)
            .unwrap();
        assert_eq!(
            owner
                .lock()
                .unwrap()
                .coding_launch_information_to_stage(first.value.attempt_id)
                .unwrap(),
            Some(BTreeMap::new())
        );
        process_coding_activation_job(owner.clone(), &owner_client)
            .await
            .unwrap();
        let first_successor = owner
            .lock()
            .unwrap()
            .coding_launch_successor_for_test(first.value.attempt_id)
            .unwrap()
            .unwrap();
        {
            let owner = owner.lock().unwrap();
            assert!(
                owner
                    .coding_launch_jobs_for_test()
                    .unwrap()
                    .iter()
                    .any(|job| job.plan == first_successor)
            );
            assert_eq!(
                owner
                    .coding_launch_information_to_stage(first_successor.value.attempt_id)
                    .unwrap(),
                Some(BTreeMap::new())
            );
            assert!(
                owner
                    .coding_checkpoint_has_pending(first.value.checkpoint_hash)
                    .unwrap()
            );
        }
        assert_eq!(
            holder.lock().unwrap().coding_used_bytes_for_test().unwrap(),
            0
        );
        owner_client.shutdown().await.unwrap();
        holder_client.shutdown().await.unwrap();
        owner_task.await.unwrap().unwrap();
        holder_task.await.unwrap().unwrap();
        drop(owner_client);
        drop(holder_client);
        drop(owner);
        drop(holder);
        for _ in 0..2 {
            let owner = Node::open(&owner_path, seed.clone()).unwrap();
            let holder = Node::open(&holder_path, holder_seed.clone()).unwrap();
            assert!(owner.claim_coding_retry(None).unwrap().is_some());
            assert_eq!(
                owner
                    .coding_launch_successor_for_test(first.value.attempt_id)
                    .unwrap(),
                Some(first_successor.clone())
            );
            assert_eq!(
                owner
                    .coding_launch_information_to_stage(first_successor.value.attempt_id)
                    .unwrap(),
                Some(BTreeMap::new())
            );
            assert!(
                owner
                    .coding_launch_information_to_stage(initial.value.attempt_id)
                    .unwrap()
                    .is_some()
            );
            assert_eq!(holder.coding_used_bytes_for_test().unwrap(), 0);
            assert_eq!(holder.coding_staged_receipt_count_for_test().unwrap(), 0);
        }
    }

    #[tokio::test]
    async fn three_member_negative_activation_rotates_verifier_into_coder() {
        let temp = tempfile::tempdir().unwrap();
        let seeds = (0_u8..5)
            .map(|index| Seed::from_bytes([160 + index; 32]))
            .collect::<Vec<_>>();
        let nodes = (0_u8..5)
            .map(|index| {
                Arc::new(Mutex::new(
                    Node::open(
                        temp.path().join(format!("node-{index}")),
                        seeds[index as usize].clone(),
                    )
                    .unwrap(),
                ))
            })
            .collect::<Vec<_>>();
        let mut clients = Vec::new();
        let mut tasks = Vec::new();
        for (index, node) in nodes.iter().enumerate() {
            let volume = temp.path().join(format!("volume-{index}"));
            std::fs::create_dir(&volume).unwrap();
            node.lock()
                .unwrap()
                .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                .unwrap();
            let mut cfg = config(node.lock().unwrap().keys().node_id());
            cfg.enable_relay_server = false;
            let (client, event_loop) = build_p2p(node.clone(), cfg).unwrap();
            clients.push(client);
            tasks.push(tokio::spawn(event_loop.run()));
        }
        let addresses = futures::future::join_all(clients.iter().map(listening_address)).await;
        let endpoints = clients
            .iter()
            .zip(addresses.iter().cloned())
            .map(|(client, address)| peer_endpoint(client, address))
            .collect::<Vec<_>>();
        let certificate = form_test_guild(&nodes, &clients, &addresses, &endpoints).await;
        for index in [4, 3] {
            let removed = nodes[index].lock().unwrap().keys().node_id();
            install_coding_test_event(
                &nodes,
                mb_core::GuildEventKind::RemoveMember { node_id: removed },
            );
        }
        let ids = nodes
            .iter()
            .take(3)
            .map(|node| node.lock().unwrap().keys().node_id())
            .collect::<Vec<_>>();
        let writer = ed25519_dalek::SigningKey::from_bytes(&[165; 32]);
        install_coding_test_event(
            &nodes,
            mb_core::GuildEventKind::RotateWriterKey {
                owner: ids[0],
                epoch: 1,
                public_key: writer.verifying_key().to_bytes(),
            },
        );
        for (client, self_id) in clients.iter().take(3).zip(&ids) {
            for (peer_id, address) in ids.iter().zip(&addresses) {
                if peer_id != self_id {
                    client
                        .add_peer_address(*peer_id, address.clone())
                        .await
                        .unwrap();
                }
            }
        }
        let state = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let member = |id| {
            state
                .active_members()
                .find(|member| member.node_id == id)
                .unwrap()
                .clone()
        };
        let guild_id = state.guild_id;
        let revision_id = Uuid::from_bytes([166; 16]);
        let sector_id =
            mb_core::make_sector_id(ids[0], revision_id, mb_core::SectorPurpose::Metadata, 0);
        let (reference, bytes) = mb_core::encrypted_sector(
            &nodes[0].lock().unwrap().keys().guild_data_key(&guild_id),
            sector_id,
            &[31],
        )
        .unwrap();
        nodes[0]
            .lock()
            .unwrap()
            .install_repaired_information_sector(guild_id, reference.clone(), &bytes)
            .unwrap();
        let mut revision = UserRevision {
            format_version: 4,
            guild_id,
            protected_root_id: Uuid::from_bytes([167; 16]),
            cipher_profile: mb_core::V1_CIPHER_PROFILE,
            revision_id,
            owner: ids[0],
            writer_epoch: 1,
            writer_public_key: writer.verifying_key().to_bytes(),
            writer_signature: Vec::new(),
            sequence: 1,
            parent: None,
            metadata_sectors: vec![reference.clone()],
            data_sectors: Vec::new(),
            sector_commitments: Some(vec![merkle_commit(&bytes).unwrap()]),
        };
        revision.sign_writer(&writer).unwrap();
        let checkpoint = GuildCheckpoint {
            format_version: 5,
            guild_id,
            genesis_hash: certificate.hash().unwrap(),
            generation: 1,
            parent: None,
            members: state.active_members().cloned().collect(),
            writer_fences: vec![mb_core::WriterFence {
                owner: ids[0],
                epoch: 1,
                public_key: writer.verifying_key().to_bytes(),
            }],
            revision_tombstones: Vec::new(),
            revisions: vec![
                SignedRecord::sign(
                    mb_core::USER_REVISION_DOMAIN,
                    revision,
                    nodes[0].lock().unwrap().keys(),
                )
                .unwrap(),
            ],
            coding_groups: Vec::new(),
            authority: Some(CheckpointAuthority {
                format_version: 1,
                membership_epoch: state.membership_epoch,
                quorum: state.quorum,
            }),
            packing_catalog: None,
        };
        let profile = CodingProfile::new(2, 1, V1_SECTOR_SIZE as u32);
        let data = [bytes, vec![0; V1_SECTOR_SIZE]];
        let plan = nodes[0]
            .lock()
            .unwrap()
            .sign_coding_attempt_plan(CodingAttemptPlan {
                format_version: 3,
                attempt_id: [161; 16],
                checkpoint_hash: checkpoint.hash().unwrap(),
                membership_epoch: state.membership_epoch,
                geometry: CodingPlanGeometry {
                    format_version: 1,
                    guild_id,
                    profile,
                    information: vec![
                        InformationRoleV2 {
                            owner: ids[0],
                            failure_domain: member(ids[0]).failure_domain,
                            sector: RangeSectorRef {
                                id: sector_id,
                                commitment: merkle_commit(&data[0]).unwrap(),
                                logical_len: reference.logical_len,
                                virtual_zero: false,
                            },
                        },
                        InformationRoleV2 {
                            owner: ids[1],
                            failure_domain: member(ids[1]).failure_domain,
                            sector: RangeSectorRef {
                                id: [168; 32],
                                commitment: mb_core::merkle_zero_commitment(profile.shard_size)
                                    .unwrap(),
                                logical_len: profile.shard_size,
                                virtual_zero: true,
                            },
                        },
                    ],
                    parity: vec![ParityPlacementV2 {
                        holder: ids[2],
                        failure_domain: member(ids[2]).failure_domain,
                        row: 0,
                    }],
                },
                delegator: ids[0],
                coding_coordinator: ids[1],
                verification_coordinator: ids[2],
                expires_at_unix_seconds: unix_seconds() + 600,
                information_roots: Some(vec![reference.root, [0; 32]]),
            })
            .unwrap();
        nodes[0]
            .lock()
            .unwrap()
            .enqueue_coding_launch_with_information(plan.clone(), Some(BTreeMap::new()))
            .unwrap();
        let keys = seeds.iter().map(KeyMaterial::from_seed).collect::<Vec<_>>();
        let shards = encode(plan.value.geometry.profile, data.to_vec()).unwrap();
        let invalid =
            crate::node::tests::test_invalid_coding_transcript(plan.clone(), &shards, &keys);
        let old_group = invalid.value.manifest.value.group.id;
        let ShardRoleV2::Parity(old_parity_role) = &invalid.value.manifest.value.group.roles[2]
        else {
            unreachable!();
        };
        let mut old_parity = shards[2].clone();
        for byte in &mut old_parity {
            *byte ^= 1;
        }
        nodes[2]
            .lock()
            .unwrap()
            .stage_coding_parity(
                &plan,
                &invalid.value.manifest,
                &VariableParityObject {
                    format_version: 2,
                    guild_id,
                    group_id: old_group,
                    shard_index: 2,
                    commitment: old_parity_role.commitment.clone(),
                    bytes: old_parity,
                },
            )
            .unwrap();
        nodes[0]
            .lock()
            .unwrap()
            .accept_coding_transcript(plan.value.coding_coordinator, invalid)
            .unwrap();
        assert_eq!(
            fresh_coding_activation_coordinators(nodes[0].clone(), &clients[0], &plan).await,
            Some((ids[2], ids[0]))
        );
        process_coding_activation_job(nodes[0].clone(), &clients[0])
            .await
            .unwrap();
        let successor = nodes[0]
            .lock()
            .unwrap()
            .coding_launch_successor_for_test(plan.value.attempt_id)
            .unwrap()
            .unwrap();
        assert_eq!(
            (
                successor.value.coding_coordinator,
                successor.value.verification_coordinator
            ),
            (ids[2], ids[0])
        );
        assert_ne!(successor.value.attempt_id, plan.value.attempt_id);
        assert_eq!(
            nodes[0]
                .lock()
                .unwrap()
                .coding_launch_information_to_stage(successor.value.attempt_id)
                .unwrap(),
            Some(BTreeMap::new())
        );
        assert!(
            nodes[2]
                .lock()
                .unwrap()
                .variable_parity_for_guild(&guild_id, &old_group, 2)
                .is_err()
        );
        let coding_tasks = nodes
            .iter()
            .take(3)
            .zip(clients.iter())
            .map(|(node, client)| {
                tokio::spawn(run_delegated_coding_jobs(node.clone(), client.clone()))
            })
            .collect::<Vec<_>>();
        tokio::time::timeout(
            Duration::from_secs(90),
            wait_for_variable_coding_groups(nodes[0].clone(), checkpoint.clone()),
        )
        .await
        .expect("three-member negative renewal did not reach verified coverage")
        .unwrap();
        let group = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap()
            .coding_groups
            .into_iter()
            .find(|group| group.retired_at_event.is_none())
            .unwrap();
        assert_ne!(group.group.id, old_group);
        for task in coding_tasks {
            task.abort();
            assert!(task.await.unwrap_err().is_cancelled());
        }
        for client in &clients {
            client.shutdown().await.unwrap();
        }
        for task in tasks {
            task.await.unwrap().unwrap();
        }
        drop(clients);
        drop(nodes);
        async fn reopen_after_coding_workers(path: std::path::PathBuf, seed: Seed) -> Node {
            tokio::time::timeout(Duration::from_secs(30), async {
                loop {
                    match Node::open(&path, seed.clone()) {
                        Ok(node) => return node,
                        Err(error)
                            if error
                                .to_string()
                                .contains("node data directory is already in use") =>
                        {
                            // Aborting an async coding worker cannot cancel a
                            // spawn_blocking call already holding its Arc<Node>.
                            tokio::time::sleep(Duration::from_millis(25)).await;
                        }
                        Err(error) => panic!("could not reopen coding node: {error:#}"),
                    }
                }
            })
            .await
            .expect("coding workers retained the node directory after shutdown")
        }
        for _ in 0..2 {
            let owner =
                reopen_after_coding_workers(temp.path().join("node-0"), seeds[0].clone()).await;
            let holder = Node::open(temp.path().join("node-2"), seeds[2].clone()).unwrap();
            assert_eq!(
                owner
                    .coding_launch_successor_for_test(plan.value.attempt_id)
                    .unwrap(),
                Some(successor.clone())
            );
            owner
                .validate_variable_checkpoint_coverage(&checkpoint, false)
                .unwrap();
            assert!(
                holder
                    .variable_parity_for_guild(&guild_id, &old_group, 2)
                    .is_err()
            );
        }
    }

