    #[tokio::test]
    async fn expired_launch_completed_staging_renews_after_reopen() {
        coding_retry_restart_fixture(true, false, false, RetryReplanningCase::ExpiredCompleted)
            .await;
    }

    #[tokio::test]
    async fn expired_dispatched_launch_recovers_with_coordinator_offline_after_reopen() {
        coding_retry_restart_fixture(true, false, false, RetryReplanningCase::ExpiredDispatched)
            .await;
    }

    #[tokio::test]
    async fn blocked_launch_staging_yields_to_healthy_launch_after_reopen() {
        coding_retry_restart_fixture(true, false, false, RetryReplanningCase::LaunchFairness).await;
    }

    #[derive(Clone, Copy, PartialEq, Eq)]
    enum RetryReplanningCase {
        None,
        Live,
        FailedChain,
        StagingRestart,
        ExpiredPartial,
        ExpiredFinalized,
        ExpiredCompleted,
        ExpiredDispatched,
        LaunchFairness,
        VerifiedEpochChange,
        VerifiedExpiry,
        RetiredAcknowledged,
    }

    fn install_coding_test_event(nodes: &[Arc<Mutex<Node>>], kind: mb_core::GuildEventKind) {
        let state = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let event = GuildEvent {
            format_version: 1,
            guild_id: state.guild_id,
            sequence: state.event_sequence + 1,
            parent: state.event_head,
            kind,
        };
        let mut signatures = nodes
            .iter()
            .filter_map(|node| {
                let node = node.lock().unwrap();
                state
                    .active_members()
                    .any(|member| member.node_id == node.keys().node_id())
                    .then(|| mb_core::sign_guild_event(&event, node.keys()).unwrap())
            })
            .collect::<Vec<_>>();
        signatures.sort_by_key(|signature| signature.signer);
        let certified = QuorumGuildEvent { event, signatures };
        for node in nodes {
            node.lock()
                .unwrap()
                .install_guild_event(certified.clone())
                .unwrap();
        }
    }

    fn install_coding_test_group_event(
        nodes: &[Arc<Mutex<Node>>],
        transcript: &SignedRecord<CodingVerificationTranscript>,
    ) {
        let state = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let event = GuildEvent {
            format_version: 2,
            guild_id: state.guild_id,
            sequence: state.event_sequence + 1,
            parent: state.event_head,
            kind: mb_core::GuildEventKind::AddCodingGroupBound {
                group: transcript.value.manifest.value.group.clone(),
                transcript_hash: *blake3::hash(&canonical_bytes(transcript).unwrap()).as_bytes(),
            },
        };
        let mut signatures = nodes
            .iter()
            .filter_map(|node| {
                let node = node.lock().unwrap();
                state
                    .active_members()
                    .any(|member| member.node_id == node.keys().node_id())
                    .then(|| mb_core::sign_guild_event(&event, node.keys()).unwrap())
            })
            .collect::<Vec<_>>();
        signatures.sort_by_key(|signature| signature.signer);
        let certified = QuorumGuildEvent { event, signatures };
        for node in nodes {
            node.lock()
                .unwrap()
                .install_coding_group_event(certified.clone(), transcript.clone())
                .unwrap();
        }
    }

    async fn coding_retry_restart_fixture(
        queue_replacement: bool,
        three_members: bool,
        stale_epoch: bool,
        replanning: RetryReplanningCase,
    ) {
        coding_retry_restart_fixture_with_cleanup_race(
            queue_replacement,
            three_members,
            stale_epoch,
            replanning,
            None,
        )
        .await;
    }

    async fn coding_retry_restart_fixture_with_cleanup_race(
        queue_replacement: bool,
        three_members: bool,
        stale_epoch: bool,
        replanning: RetryReplanningCase,
        cleanup_race: Option<CodingCleanupRace>,
    ) {
        let active_count = if three_members {
            3
        } else if stale_epoch {
            4
        } else {
            5
        };
        let temp = tempfile::tempdir().unwrap();
        let seeds = (201_u8..206)
            .map(|byte| Seed::from_bytes([byte; 32]))
            .collect::<Vec<_>>();
        let open_nodes = || {
            seeds
                .iter()
                .enumerate()
                .map(|(index, seed)| {
                    Arc::new(Mutex::new(
                        Node::open(temp.path().join(format!("node-{index}")), seed.clone())
                            .unwrap(),
                    ))
                })
                .collect::<Vec<_>>()
        };
        let mut nodes = open_nodes();
        let mut clients = Vec::new();
        let mut network_tasks = Vec::new();
        for (index, node) in nodes.iter().enumerate() {
            let volume = temp.path().join(format!("volume-{index}"));
            std::fs::create_dir(&volume).unwrap();
            node.lock()
                .unwrap()
                .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                .unwrap();
            let mut cfg = config(node.lock().unwrap().keys().node_id());
            cfg.enable_relay_server = false;
            let (client, event_loop) = build_p2p(node.clone(), cfg).unwrap();
            clients.push(client);
            network_tasks.push(tokio::spawn(event_loop.run()));
        }
        let addresses = futures::future::join_all(clients.iter().map(listening_address)).await;
        let endpoints = clients
            .iter()
            .zip(addresses.iter().cloned())
            .map(|(client, address)| peer_endpoint(client, address))
            .collect::<Vec<_>>();
        let certificate = form_test_guild(&nodes, &clients, &addresses, &endpoints).await;
        if three_members {
            for index in [4, 3] {
                let removed = nodes[index].lock().unwrap().keys().node_id();
                install_coding_test_event(
                    &nodes,
                    mb_core::GuildEventKind::RemoveMember { node_id: removed },
                );
            }
        }
        if replanning == RetryReplanningCase::ExpiredDispatched {
            install_coding_test_event(
                &nodes,
                mb_core::GuildEventKind::SetQuorum {
                    policy: QuorumPolicy {
                        format_version: 1,
                        rule: QuorumRule::Majority,
                    },
                },
            );
        }
        let owner = nodes[0].lock().unwrap().keys().node_id();
        let writer = ed25519_dalek::SigningKey::from_bytes(&[211; 32]);
        install_coding_test_event(
            &nodes,
            mb_core::GuildEventKind::RotateWriterKey {
                owner,
                epoch: 1,
                public_key: writer.verifying_key().to_bytes(),
            },
        );
        let state = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let guild_id = state.guild_id;
        let revision_id = Uuid::from_bytes([212; 16]);
        let sector_id =
            mb_core::make_sector_id(owner, revision_id, mb_core::SectorPurpose::Metadata, 0);
        let (reference, bytes) = mb_core::encrypted_sector(
            &nodes[0].lock().unwrap().keys().guild_data_key(&guild_id),
            sector_id,
            &[42],
        )
        .unwrap();
        nodes[0]
            .lock()
            .unwrap()
            .install_repaired_information_sector(guild_id, reference.clone(), &bytes)
            .unwrap();
        let member = |index: usize| {
            state
                .active_members()
                .find(|member| member.node_id == nodes[index].lock().unwrap().keys().node_id())
                .unwrap()
                .clone()
        };
        let mut geometry = mb_core::CodingPlanGeometry {
            format_version: 1,
            guild_id,
            profile: CodingProfile::new(1, 1, V1_SECTOR_SIZE as u32),
            information: vec![mb_core::InformationRoleV2 {
                owner,
                failure_domain: member(0).failure_domain,
                sector: mb_core::RangeSectorRef {
                    id: sector_id,
                    commitment: merkle_commit(&bytes).unwrap(),
                    logical_len: reference.logical_len,
                    virtual_zero: false,
                },
            }],
            parity: vec![mb_core::ParityPlacementV2 {
                holder: member(1).node_id,
                failure_domain: member(1).failure_domain,
                row: 0,
            }],
        };
        if replanning == RetryReplanningCase::RetiredAcknowledged {
            geometry.parity.push(mb_core::ParityPlacementV2 {
                holder: member(2).node_id,
                failure_domain: member(2).failure_domain,
                row: 1,
            });
            geometry.profile.parity_shards = 2;
        }
        let mut old = CodingAttemptPlan {
            format_version: 2,
            attempt_id: [213; 16],
            checkpoint_hash: [214; 32],
            membership_epoch: state.membership_epoch,
            geometry,
            delegator: owner,
            coding_coordinator: member(1).node_id,
            verification_coordinator: member(2).node_id,
            expires_at_unix_seconds: unix_seconds() + 600,
            information_roots: Some(vec![reference.root]),
        };
        let mut replacement = old.clone();
        replacement.format_version = 3;
        replacement.attempt_id = [215; 16];
        if three_members {
            // A different lane is eligible even though the old lane lacks two fresh coordinators.
            old.geometry.information[0].sector.id = [216; 32];
            old.checkpoint_hash = [217; 32];
        }
        let old = nodes[0]
            .lock()
            .unwrap()
            .sign_coding_attempt_plan(old)
            .unwrap();
        let failure = SignedRecord::sign(
            CODING_FAILURE_REPORT_DOMAIN,
            mb_core::CodingFailureReport {
                format_version: 1,
                failed_at_unix_seconds: unix_seconds(),
                plan: old.clone(),
                error_hash: [218; 32],
            },
            nodes[1].lock().unwrap().keys(),
        )
        .unwrap();
        let expired_plan = if three_members {
            None
        } else {
            let mut plan = old.value.clone();
            plan.attempt_id = [219; 16];
            if matches!(
                replanning,
                RetryReplanningCase::Live
                    | RetryReplanningCase::FailedChain
                    | RetryReplanningCase::VerifiedEpochChange
                    | RetryReplanningCase::VerifiedExpiry
                    | RetryReplanningCase::RetiredAcknowledged
            ) {
                plan.format_version = 3;
            }
            plan.coding_coordinator = member(3).node_id;
            plan.verification_coordinator = member(4).node_id;
            plan.expires_at_unix_seconds = unix_seconds()
                + if replanning == RetryReplanningCase::VerifiedExpiry {
                    // Initial verification must finish before real expiry even
                    // when the full workspace suite competes for CPU and I/O.
                    120
                } else if stale_epoch
                    || replanning == RetryReplanningCase::Live
                    || replanning == RetryReplanningCase::FailedChain
                    || replanning == RetryReplanningCase::VerifiedEpochChange
                    || replanning == RetryReplanningCase::RetiredAcknowledged
                {
                    600
                } else {
                    3
                };
            Some(
                nodes[0]
                    .lock()
                    .unwrap()
                    .sign_coding_attempt_plan(plan)
                    .unwrap(),
            )
        };
        let old_job = CodingRetryJob {
            format_version: 1,
            failure,
            retry_plan: expired_plan.clone(),
            complete: matches!(
                replanning,
                RetryReplanningCase::Live
                    | RetryReplanningCase::FailedChain
                    | RetryReplanningCase::VerifiedEpochChange
                    | RetryReplanningCase::VerifiedExpiry
                    | RetryReplanningCase::ExpiredPartial
                    | RetryReplanningCase::ExpiredFinalized
                    | RetryReplanningCase::ExpiredCompleted
                    | RetryReplanningCase::ExpiredDispatched
            ),
            error: None,
        };
        nodes[0]
            .lock()
            .unwrap()
            .install_historical_coding_retry_for_test(&old_job)
            .unwrap();
        let child_job = if replanning == RetryReplanningCase::FailedChain {
            let failed = expired_plan.as_ref().unwrap();
            let mut child = failed.value.clone();
            child.attempt_id = [1; 16];
            child.expires_at_unix_seconds = unix_seconds() + 3;
            let child = nodes[0]
                .lock()
                .unwrap()
                .sign_coding_attempt_plan(child)
                .unwrap();
            let failure = SignedRecord::sign(
                CODING_FAILURE_REPORT_DOMAIN,
                mb_core::CodingFailureReport {
                    format_version: 1,
                    failed_at_unix_seconds: unix_seconds(),
                    plan: failed.clone(),
                    error_hash: [221; 32],
                },
                nodes[3].lock().unwrap().keys(),
            )
            .unwrap();
            let job = CodingRetryJob {
                format_version: 1,
                failure,
                retry_plan: Some(child),
                complete: false,
                error: None,
            };
            nodes[0]
                .lock()
                .unwrap()
                .install_historical_coding_retry_for_test(&job)
                .unwrap();
            Some(job)
        } else {
            None
        };
        let partial_plan = child_job
            .as_ref()
            .and_then(|job| job.retry_plan.as_ref())
            .or(expired_plan.as_ref());
        if let Some(plan) = partial_plan.filter(|_| {
            !matches!(
                replanning,
                RetryReplanningCase::ExpiredPartial
                    | RetryReplanningCase::ExpiredFinalized
                    | RetryReplanningCase::ExpiredCompleted
                    | RetryReplanningCase::ExpiredDispatched
            )
        }) {
            // A partial durable upload must be cleaned before renewal or supersession.
            nodes[1]
                .lock()
                .unwrap()
                .reserve_coding_parity(plan, 1)
                .unwrap();
            let (manifest, parity) = nodes[3]
                .lock()
                .unwrap()
                .encode_delegated_coding(plan, vec![Some(bytes.clone())])
                .unwrap();
            assert_eq!(
                nodes[1]
                    .lock()
                    .unwrap()
                    .write_coding_parity_range(
                        plan,
                        &manifest,
                        1,
                        0,
                        &parity[0][..MERKLE_LEAF_SIZE]
                    )
                    .unwrap(),
                MERKLE_LEAF_SIZE as u32
            );
        }
        if replanning == RetryReplanningCase::Live {
            let plan = expired_plan.as_ref().unwrap().clone();
            nodes[3]
                .lock()
                .unwrap()
                .enqueue_delegated_coding(owner, plan)
                .unwrap();
        }
        if replanning == RetryReplanningCase::RetiredAcknowledged {
            let plan = expired_plan.as_ref().unwrap().clone();
            for (local, remote) in [(0, 3), (0, 1), (0, 2), (3, 0), (3, 1), (3, 2)] {
                let id = nodes[remote].lock().unwrap().keys().node_id();
                clients[local]
                    .add_peer_address(id, addresses[remote].clone())
                    .await
                    .unwrap();
                clients[local].profile(id).await.unwrap();
            }
            process_coding_retry_job(nodes[0].clone(), &clients[0], &old_job)
                .await
                .unwrap();
            {
                let delegator = nodes[0].lock().unwrap();
                let acknowledged = delegator
                    .coding_retry_evidence_for_test(old.value.attempt_id)
                    .unwrap();
                assert!(acknowledged.complete);
                assert_eq!(acknowledged.retry_plan, Some(plan.clone()));
                assert!(delegator.claim_coding_retry(None).unwrap().is_none());
                for id in [old.value.attempt_id, plan.value.attempt_id] {
                    assert!(
                        delegator
                            .coding_launch_information_to_stage(id)
                            .unwrap()
                            .is_none()
                    );
                }
            }
            let (manifest, parity) = nodes[3]
                .lock()
                .unwrap()
                .encode_delegated_coding(&plan, vec![Some(bytes.clone())])
                .unwrap();
            let holder = nodes[1].lock().unwrap().keys().node_id();
            assert_eq!(
                clients[3]
                    .reserve_coding_parity(holder, plan.clone(), 1)
                    .await
                    .unwrap(),
                MERKLE_LEAF_SIZE as u32
            );
            clients[3]
                .upload_coding_parity_range(
                    holder,
                    plan.clone(),
                    manifest.clone(),
                    1,
                    MERKLE_LEAF_SIZE as u32,
                    parity[0][MERKLE_LEAF_SIZE..].to_vec(),
                )
                .await
                .unwrap();
            clients[3]
                .finalize_coding_parity(holder, plan.clone(), manifest.clone(), 1)
                .await
                .unwrap();
            let partial_holder = nodes[2].lock().unwrap().keys().node_id();
            clients[3]
                .reserve_coding_parity(partial_holder, plan.clone(), 2)
                .await
                .unwrap();
            clients[3]
                .upload_coding_parity_range(
                    partial_holder,
                    plan.clone(),
                    manifest,
                    2,
                    0,
                    parity[1][..MERKLE_LEAF_SIZE].to_vec(),
                )
                .await
                .unwrap();
            assert_eq!(
                nodes[1]
                    .lock()
                    .unwrap()
                    .coding_used_bytes_for_test()
                    .unwrap(),
                V1_SECTOR_SIZE as u64
            );
            assert_eq!(
                nodes[1]
                    .lock()
                    .unwrap()
                    .coding_staged_receipt_count_for_test()
                    .unwrap(),
                1
            );
            assert_eq!(
                nodes[2]
                    .lock()
                    .unwrap()
                    .coding_reservation_count_for_test()
                    .unwrap(),
                1
            );
            install_coding_test_event(
                &nodes,
                mb_core::GuildEventKind::RelabelMember {
                    node_id: member(4).node_id,
                    failure_domain: "descriptorless-retirement-unrelated-change".to_owned(),
                },
            );
            assert!(
                clients[3]
                    .retire_coding_attempt(owner, plan.clone())
                    .await
                    .unwrap()
            );
            // Stop the coder after the delegator's fence commits, before the
            // coder issues any deletion. It remains offline for recovery.
            clients[3].shutdown().await.unwrap();
            // A delayed delegation acknowledgement cannot turn that fence
            // into terminal cleanup evidence either.
            nodes[0]
                .lock()
                .unwrap()
                .complete_coding_retry(old.value.attempt_id)
                .unwrap();
            let volume = temp.path().join("volume-1");
            let offline = temp.path().join("offline-volume-1");
            std::fs::rename(&volume, &offline).unwrap();
            nodes[1]
                .lock()
                .unwrap()
                .configure_storage_volumes(std::slice::from_ref(&volume), 4 * 1024 * 1024, 0)
                .unwrap();
            let claimed = nodes[0]
                .lock()
                .unwrap()
                .claim_coding_retry(None)
                .unwrap()
                .unwrap();
            assert!(!claimed.complete);
            assert_eq!(claimed.retry_plan, Some(plan.clone()));
            process_coding_retry_job(nodes[0].clone(), &clients[0], &claimed)
                .await
                .unwrap();
            let deferred = nodes[0]
                .lock()
                .unwrap()
                .coding_retry_evidence_for_test(old.value.attempt_id)
                .unwrap();
            assert!(deferred.complete);
            assert!(deferred.error.is_none());
            assert!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .coding_holder_cleanup_count_for_test()
                    .unwrap()
                    > 0,
                "offline holder deletion must remain a durable obligation"
            );
            assert_eq!(
                nodes[2]
                    .lock()
                    .unwrap()
                    .coding_reservation_count_for_test()
                    .unwrap(),
                0
            );
            for (index, client) in clients.iter().enumerate() {
                if index != 3 {
                    client.shutdown().await.unwrap();
                }
            }
            for task in network_tasks {
                task.await.unwrap().unwrap();
            }
            drop(clients);
            drop(nodes);
            nodes = open_nodes();
            assert_eq!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .coding_retry_evidence_for_test(old.value.attempt_id)
                    .unwrap(),
                deferred
            );
            assert!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .claim_coding_retry(None)
                    .unwrap()
                    .is_none()
            );
            std::fs::rename(&offline, &volume).unwrap();
            nodes[1]
                .lock()
                .unwrap()
                .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                .unwrap();
            clients = Vec::new();
            network_tasks = Vec::new();
            // No event loop or worker is restarted for the silent coder.
            for index in [0, 1, 2, 4] {
                let mut cfg = config(nodes[index].lock().unwrap().keys().node_id());
                cfg.enable_relay_server = false;
                let (client, event_loop) = build_p2p(nodes[index].clone(), cfg).unwrap();
                clients.push(client);
                network_tasks.push(tokio::spawn(event_loop.run()));
            }
            let addresses = futures::future::join_all(clients.iter().map(listening_address)).await;
            for index in [1, 2] {
                let id = nodes[index].lock().unwrap().keys().node_id();
                clients[0]
                    .add_peer_address(id, addresses[index].clone())
                    .await
                    .unwrap();
                clients[0].profile(id).await.unwrap();
            }
            let worker = tokio::spawn(run_coding_holder_cleanup_jobs(
                nodes[0].clone(),
                clients[0].clone(),
            ));
            let deadline = tokio::time::Instant::now() + Duration::from_secs(45);
            loop {
                assert!(!worker.is_finished());
                if nodes[0]
                    .lock()
                    .unwrap()
                    .coding_holder_cleanup_count_for_test()
                    .unwrap()
                    == 0
                {
                    break;
                }
                assert!(
                    tokio::time::Instant::now() < deadline,
                    "descriptor-less holder cleanup obligation did not converge"
                );
                tokio::time::sleep(Duration::from_millis(100)).await;
            }
            worker.abort();
            let _ = worker.await;
            for client in &clients {
                client.shutdown().await.unwrap();
            }
            for task in network_tasks {
                task.await.unwrap().unwrap();
            }
            drop(clients);
            drop(nodes);
            for _ in 0..2 {
                nodes = open_nodes();
                for node in &nodes {
                    let node = node.lock().unwrap();
                    assert_eq!(node.coding_used_bytes_for_test().unwrap(), 0);
                    assert_eq!(node.coding_staged_receipt_count_for_test().unwrap(), 0);
                    assert_eq!(node.coding_reservation_count_for_test().unwrap(), 0);
                }
                let delegator = nodes[0].lock().unwrap();
                let retained = delegator
                    .coding_retry_evidence_for_test(old.value.attempt_id)
                    .unwrap();
                assert!(retained.complete);
                assert_eq!(retained.failure, old_job.failure);
                assert_eq!(retained.retry_plan, Some(plan.clone()));
                assert_eq!(
                    delegator
                        .retired_coding_plan_for_test(plan.value.attempt_id)
                        .unwrap(),
                    Some(plan.clone())
                );
                assert!(delegator.claim_coding_retry(None).unwrap().is_none());
                drop(delegator);
                drop(nodes);
            }
            return;
        }
        let mut accepted_evidence = None;
        let mut retired_evidence = None;
        let mut delayed_failure = None;
        let mut failed_evidence = None;
        let mut extra_stale_plan = None;
        if matches!(
            replanning,
            RetryReplanningCase::VerifiedEpochChange | RetryReplanningCase::VerifiedExpiry
        ) {
            nodes[0]
                .lock()
                .unwrap()
                .install_coding_launch_for_test(&crate::node::CodingLaunchJob {
                    format_version: 1,
                    plan: expired_plan.as_ref().unwrap().clone(),
                    dispatched: true,
                    error: None,
                })
                .unwrap();
            for (remote, remote_node) in nodes.iter().enumerate() {
                if remote != 3 {
                    let id = remote_node.lock().unwrap().keys().node_id();
                    clients[3]
                        .add_peer_address(id, addresses[remote].clone())
                        .await
                        .unwrap();
                    clients[3].profile(id).await.unwrap();
                }
            }
            let plan = expired_plan.as_ref().unwrap().clone();
            if cleanup_race == Some(CodingCleanupRace::Failure) {
                let coder_id = plan.value.coding_coordinator;
                clients[0]
                    .add_peer_address(coder_id, addresses[3].clone())
                    .await
                    .unwrap();
                clients[0].profile(coder_id).await.unwrap();
                clients[0]
                    .delegate_coding_attempt(coder_id, plan.clone())
                    .await
                    .unwrap();
                assert_eq!(
                    nodes[3]
                        .lock()
                        .unwrap()
                        .claim_delegated_coding()
                        .unwrap()
                        .unwrap()
                        .state,
                    DelegatedCodingJobState::Running
                );
            } else if matches!(
                cleanup_race,
                Some(CodingCleanupRace::Delegated | CodingCleanupRace::Retired)
            ) {
                let coder = nodes[3].lock().unwrap();
                coder.enqueue_delegated_coding(owner, plan.clone()).unwrap();
                assert_eq!(
                    coder.claim_delegated_coding().unwrap().unwrap().state,
                    DelegatedCodingJobState::Running
                );
            }
            let job = DelegatedCodingJob {
                format_version: 1,
                plan,
                state: DelegatedCodingJobState::Pending,
                transcript: None,
                error: None,
            };
            let transcript = execute_delegated_coding(nodes[3].clone(), &clients[3], &job)
                .await
                .unwrap();
            accepted_evidence = Some(transcript.clone());
            if matches!(
                cleanup_race,
                Some(CodingCleanupRace::Delegated | CodingCleanupRace::Retired)
            ) {
                nodes[3]
                    .lock()
                    .unwrap()
                    .record_delegated_coding_result(job.plan.value.attempt_id, transcript.clone())
                    .unwrap();
            }
            if cleanup_race == Some(CodingCleanupRace::Retired) {
                // A second stale owner must not be hidden behind a permanently
                // rejected Submitting job after a membership transition.
                let mut value = job.plan.value.clone();
                value.attempt_id = [250; 16];
                let extra = nodes[0]
                    .lock()
                    .unwrap()
                    .sign_coding_attempt_plan(value)
                    .unwrap();
                nodes[3]
                    .lock()
                    .unwrap()
                    .enqueue_delegated_coding(owner, extra.clone())
                    .unwrap();
                let (manifest, parity) = nodes[3]
                    .lock()
                    .unwrap()
                    .encode_delegated_coding(&extra, vec![Some(bytes.clone())])
                    .unwrap();
                {
                    let mut holder = nodes[1].lock().unwrap();
                    holder.reserve_coding_parity(&extra, 1).unwrap();
                    holder
                        .write_coding_parity_range(
                            &extra,
                            &manifest,
                            1,
                            0,
                            &parity[0][..MERKLE_LEAF_SIZE],
                        )
                        .unwrap();
                }
                assert!(
                    !clients[3]
                        .coding_attempt_is_retired(owner, job.plan.clone())
                        .await
                        .unwrap()
                );
                assert!(
                    nodes[0]
                        .lock()
                        .unwrap()
                        .retired_coding_plan_for_test(job.plan.value.attempt_id)
                        .unwrap()
                        .is_none()
                );
                extra_stale_plan = Some(extra);
            }
            if cleanup_race == Some(CodingCleanupRace::Failure) {
                delayed_failure = Some(
                    nodes[3]
                        .lock()
                        .unwrap()
                        .record_delegated_coding_failure(
                            job.plan.value.attempt_id,
                            "result delivery interrupted before submission",
                        )
                        .unwrap(),
                );
                accepted_evidence = None;
                failed_evidence = Some(transcript.clone());
            }
            if cleanup_race.is_none() {
                submit_delegated_coding_result(nodes[3].clone(), &clients[3], transcript.clone())
                    .await
                    .unwrap();
            }
            if replanning == RetryReplanningCase::VerifiedEpochChange {
                install_coding_test_event(
                    &nodes,
                    mb_core::GuildEventKind::RelabelMember {
                        node_id: member(2).node_id,
                        failure_domain: "unrelated-verified-placement-change".to_owned(),
                    },
                );
                replacement.membership_epoch += 1;
            } else {
                let deadline = expired_plan.as_ref().unwrap().value.expires_at_unix_seconds;
                tokio::time::sleep(Duration::from_secs(
                    deadline.saturating_sub(unix_seconds()) + 1,
                ))
                .await;
            }
            if let Some(race) = cleanup_race {
                // Pause at the exact production boundary after claim and the
                // first evidence read, before delegator-owned retirement.
                let claimed = nodes[0]
                    .lock()
                    .unwrap()
                    .claim_coding_launch()
                    .unwrap()
                    .unwrap();
                assert!(
                    !nodes[0]
                        .lock()
                        .unwrap()
                        .coding_launch_has_verified_result(&claimed.plan)
                        .unwrap()
                );
                if race == CodingCleanupRace::Retired {
                    let volume = temp.path().join("volume-1");
                    std::fs::rename(&volume, temp.path().join("offline-volume-1")).unwrap();
                    nodes[1]
                        .lock()
                        .unwrap()
                        .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                        .unwrap();
                    assert!(
                        clients[3]
                            .retire_coding_attempt(owner, claimed.plan.clone())
                            .await
                            .unwrap()
                    );
                    assert!(
                        dispatch_claimed_coding_launch(
                            nodes[0].clone(),
                            &clients[0],
                            claimed.clone()
                        )
                        .await
                        .unwrap()
                    );
                    assert!(
                        nodes[0]
                            .lock()
                            .unwrap()
                            .coding_holder_cleanup_count_for_test()
                            .unwrap()
                            > 0,
                        "offline retired holder must retain a cleanup obligation"
                    );
                    assert!(
                        submit_delegated_coding_result(
                            nodes[3].clone(),
                            &clients[3],
                            transcript.clone()
                        )
                        .await
                        .is_err()
                    );
                    assert_eq!(
                        nodes[0]
                            .lock()
                            .unwrap()
                            .retired_coding_plan_for_test(claimed.plan.value.attempt_id)
                            .unwrap(),
                        Some(claimed.plan.clone())
                    );
                    process_delegated_coding_job(nodes[3].clone(), &clients[3])
                        .await
                        .unwrap();
                    let coder = nodes[3].lock().unwrap();
                    let pending = coder.claim_delegated_coding().unwrap().unwrap();
                    assert_eq!(pending.plan, claimed.plan);
                    assert_eq!(pending.state, DelegatedCodingJobState::Submitting);
                    assert_eq!(pending.transcript, Some(transcript.clone()));
                    assert_eq!(
                        coder
                            .delegated_coding_jobs_for_test()
                            .unwrap()
                            .iter()
                            .filter(|job| job.state != DelegatedCodingJobState::Complete)
                            .count(),
                        2
                    );
                    accepted_evidence = None;
                    retired_evidence = Some(transcript.clone());
                } else if race == CodingCleanupRace::Failure {
                    abort_delegated_coding(nodes[3].clone(), &clients[3], &job)
                        .await
                        .unwrap();
                    submit_delegated_coding_failure(
                        nodes[3].clone(),
                        &clients[3],
                        delayed_failure.clone().unwrap(),
                    )
                    .await
                    .unwrap();
                    nodes[3]
                        .lock()
                        .unwrap()
                        .complete_delegated_coding(job.plan.value.attempt_id)
                        .unwrap();
                    assert!(
                        dispatch_claimed_coding_launch(
                            nodes[0].clone(),
                            &clients[0],
                            claimed.clone()
                        )
                        .await
                        .unwrap()
                    );
                    let node = nodes[0].lock().unwrap();
                    node.defer_coding_launch(
                        claimed.plan.value.attempt_id,
                        "late selection deferral",
                    )
                    .unwrap();
                    node.complete_coding_launch(claimed.plan.value.attempt_id)
                        .unwrap();
                    assert!(node.coding_launch_jobs_for_test().unwrap().is_empty());
                    assert_eq!(
                        node.coding_retry_evidence_for_test(claimed.plan.value.attempt_id)
                            .unwrap()
                            .failure,
                        *delayed_failure.as_ref().unwrap()
                    );
                    assert!(
                        node.retired_coding_plan_for_test(claimed.plan.value.attempt_id)
                            .unwrap()
                            .is_none()
                    );
                } else {
                    submit_delegated_coding_result(
                        nodes[3].clone(),
                        &clients[3],
                        transcript.clone(),
                    )
                    .await
                    .unwrap();
                }
                match race {
                    CodingCleanupRace::Launch => {
                        assert!(
                            dispatch_claimed_coding_launch(nodes[0].clone(), &clients[0], claimed)
                                .await
                                .unwrap()
                        );
                    }
                    CodingCleanupRace::Delegated => {
                        process_delegated_coding_job(nodes[3].clone(), &clients[3])
                            .await
                            .unwrap();
                        assert!(
                            nodes[3]
                                .lock()
                                .unwrap()
                                .claim_delegated_coding()
                                .unwrap()
                                .is_none()
                        );
                    }
                    CodingCleanupRace::Retired => {}
                    CodingCleanupRace::Failure => {}
                }
                if !matches!(
                    race,
                    CodingCleanupRace::Retired | CodingCleanupRace::Failure
                ) {
                    assert_eq!(
                        nodes[0]
                            .lock()
                            .unwrap()
                            .claim_coding_activation()
                            .unwrap()
                            .unwrap()
                            .transcript,
                        transcript
                    );
                    assert_eq!(
                        nodes[1]
                            .lock()
                            .unwrap()
                            .coding_staged_receipt_count_for_test()
                            .unwrap(),
                        1
                    );
                    assert_eq!(
                        nodes[1]
                            .lock()
                            .unwrap()
                            .coding_used_bytes_for_test()
                            .unwrap(),
                        V1_SECTOR_SIZE as u64
                    );
                } else {
                    assert!(
                        nodes[0]
                            .lock()
                            .unwrap()
                            .claim_coding_activation()
                            .unwrap()
                            .is_none()
                    );
                }
            }
        }
        if let Some(job) = &child_job {
            assert!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .retire_coding_retry_plan(job.retry_plan.as_ref().unwrap())
                    .unwrap()
            );
        }
        if stale_epoch {
            let removed = nodes[4].lock().unwrap().keys().node_id();
            install_coding_test_event(
                &nodes,
                mb_core::GuildEventKind::RemoveMember { node_id: removed },
            );
            replacement.membership_epoch += 1;
        }
        let state = nodes[0]
            .lock()
            .unwrap()
            .dynamic_guild_state()
            .unwrap()
            .unwrap();
        let mut revision = UserRevision {
            format_version: 3,
            guild_id,
            protected_root_id: Uuid::from_bytes([220; 16]),
            cipher_profile: mb_core::V1_CIPHER_PROFILE,
            revision_id,
            owner,
            writer_epoch: 1,
            writer_public_key: writer.verifying_key().to_bytes(),
            writer_signature: Vec::new(),
            sequence: 1,
            parent: None,
            metadata_sectors: vec![reference],
            data_sectors: Vec::new(),
            sector_commitments: None,
        };
        revision.sign_writer(&writer).unwrap();
        let mut checkpoint = GuildCheckpoint {
            format_version: 4,
            guild_id,
            genesis_hash: certificate.hash().unwrap(),
            generation: 1,
            parent: None,
            members: state.active_members().cloned().collect(),
            writer_fences: vec![mb_core::WriterFence {
                owner,
                epoch: 1,
                public_key: writer.verifying_key().to_bytes(),
            }],
            revision_tombstones: Vec::new(),
            revisions: vec![
                SignedRecord::sign(
                    mb_core::USER_REVISION_DOMAIN,
                    revision,
                    nodes[0].lock().unwrap().keys(),
                )
                .unwrap(),
            ],
            coding_groups: Vec::new(),
            authority: None,
            packing_catalog: None,
        };
        let production_lane = || VariableCodingLane {
            geometry: replacement.geometry.clone(),
            information_roots: replacement.information_roots.clone().unwrap(),
            packed_information: BTreeMap::new(),
        };
        let mut expired_launch = None;
        let mut early_expired_handoff = false;
        let mut blocked_launch = None;
        if replanning == RetryReplanningCase::LaunchFairness {
            let blocked_owner = member(2).node_id;
            let blocked_sector = mb_core::make_sector_id(
                blocked_owner,
                Uuid::from_bytes([222; 16]),
                mb_core::SectorPurpose::Metadata,
                0,
            );
            let (_, blocked_bytes) = mb_core::encrypted_sector(
                &nodes[2].lock().unwrap().keys().guild_data_key(&guild_id),
                blocked_sector,
                &[43],
            )
            .unwrap();
            let profile = mb_core::PackingProfile {
                format_version: 1,
                sector_size: V1_SECTOR_SIZE as u32,
                slot_size: MERKLE_LEAF_SIZE as u32,
            };
            let packed = mb_core::pack_incremental(
                profile,
                None,
                vec![mb_core::PackingInput {
                    owner: blocked_owner,
                    protected_root: [224; 32],
                    object_id: blocked_sector,
                    source_commitment: Some(merkle_commit(&blocked_bytes).unwrap()),
                    bytes: blocked_bytes,
                }],
            )
            .unwrap();
            let packed_sector = packed.sectors[0].clone();
            let blocked_bytes = packed_sector.bytes.clone();
            let mut value = replacement.clone();
            value.format_version = 2;
            value.attempt_id = [0; 16];
            value.attempt_id[15] = 1;
            value.checkpoint_hash = [223; 32];
            value.geometry.information[0].owner = blocked_owner;
            value.geometry.information[0].failure_domain = member(2).failure_domain.clone();
            value.geometry.information[0].sector.id = packed_sector.descriptor.id;
            value.geometry.information[0].sector.logical_len = V1_SECTOR_SIZE as u32;
            value.geometry.information[0].sector.commitment =
                merkle_commit(&blocked_bytes).unwrap();
            value.geometry.parity[0].holder = member(4).node_id;
            value.geometry.parity[0].failure_domain = member(4).failure_domain.clone();
            value.information_roots = Some(vec![packed_sector.descriptor.flat_root]);
            value.coding_coordinator = member(3).node_id;
            value.verification_coordinator = member(4).node_id;
            let plan = {
                let mut node = nodes[0].lock().unwrap();
                node.store_packed_sector(guild_id, profile, packed_sector)
                    .unwrap();
                assert_eq!(
                    node.sector_for_guild(&guild_id, &value.geometry.information[0].sector.id)
                        .unwrap(),
                    blocked_bytes
                );
                let plan = node.sign_coding_attempt_plan(value).unwrap();
                node.enqueue_coding_launch_with_information(plan.clone(), Some(BTreeMap::new()))
                    .unwrap();
                plan
            };
            nodes[2]
                .lock()
                .unwrap()
                .reserve_coding_information(&plan, 0)
                .unwrap();
            nodes[2]
                .lock()
                .unwrap()
                .write_coding_information_range(&plan, 0, 0, &blocked_bytes[..MERKLE_LEAF_SIZE])
                .unwrap();
            blocked_launch = Some(plan);
            let volume = temp.path().join("volume-2");
            std::fs::rename(&volume, temp.path().join("offline-volume-2")).unwrap();
            nodes[2]
                .lock()
                .unwrap()
                .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                .unwrap();
            assert!(
                !dispatch_next_coding_launch(nodes[0].clone(), &clients[0])
                    .await
                    .unwrap()
            );
        }
        if matches!(
            replanning,
            RetryReplanningCase::StagingRestart
                | RetryReplanningCase::ExpiredPartial
                | RetryReplanningCase::ExpiredFinalized
                | RetryReplanningCase::ExpiredCompleted
                | RetryReplanningCase::ExpiredDispatched
        ) {
            let peers = nodes[0]
                .lock()
                .unwrap()
                .guild_summary()
                .unwrap()
                .unwrap()
                .peers;
            queue_variable_coding_lanes(
                nodes[0].clone(),
                &clients[0],
                owner,
                replacement.checkpoint_hash,
                replacement.membership_epoch,
                &peers,
                vec![production_lane()],
            )
            .await
            .unwrap();
            let mut pending = nodes[0]
                .lock()
                .unwrap()
                .claim_coding_launch()
                .unwrap()
                .unwrap();
            if replanning != RetryReplanningCase::StagingRestart {
                let node = nodes[0].lock().unwrap();
                let mut value = pending.plan.value.clone();
                value.expires_at_unix_seconds = unix_seconds()
                    + if replanning == RetryReplanningCase::ExpiredDispatched {
                        120
                    } else {
                        3
                    };
                if matches!(
                    replanning,
                    RetryReplanningCase::ExpiredCompleted | RetryReplanningCase::ExpiredDispatched
                ) {
                    value.coding_coordinator = member(3).node_id;
                    value.verification_coordinator = member(4).node_id;
                }
                pending.plan = node.sign_coding_attempt_plan(value).unwrap();
                node.install_coding_launch_for_test(&pending).unwrap();
                expired_launch = Some(pending.plan.clone());
            }
            assert!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .coding_launch_information_to_stage(pending.plan.value.attempt_id)
                    .unwrap()
                    .is_some()
            );
            {
                let mut node = nodes[0].lock().unwrap();
                assert_eq!(node.coding_used_bytes_for_test().unwrap(), 0);
                node.reserve_coding_information(&pending.plan, 0).unwrap();
                node.write_coding_information_range(
                    &pending.plan,
                    0,
                    0,
                    &bytes[..MERKLE_LEAF_SIZE],
                )
                .unwrap();
                if replanning == RetryReplanningCase::ExpiredFinalized {
                    node.write_coding_information_range(
                        &pending.plan,
                        0,
                        MERKLE_LEAF_SIZE as u32,
                        &bytes[MERKLE_LEAF_SIZE..],
                    )
                    .unwrap();
                    node.finish_coding_information_upload(&pending.plan, 0)
                        .unwrap();
                    assert_eq!(node.coding_staged_receipt_count_for_test().unwrap(), 1);
                }
                if !matches!(
                    replanning,
                    RetryReplanningCase::ExpiredCompleted | RetryReplanningCase::ExpiredDispatched
                ) {
                    let volume = temp.path().join("volume-0");
                    std::fs::rename(&volume, temp.path().join("offline-volume-0")).unwrap();
                    node.configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                        .unwrap();
                }
            }
            if replanning == RetryReplanningCase::ExpiredDispatched {
                assert!(
                    dispatch_next_coding_launch(nodes[0].clone(), &clients[0])
                        .await
                        .unwrap()
                );
                assert!(
                    nodes[0]
                        .lock()
                        .unwrap()
                        .claim_coding_launch()
                        .unwrap()
                        .is_none()
                );
                nodes[1]
                    .lock()
                    .unwrap()
                    .reserve_coding_parity(&pending.plan, 1)
                    .unwrap();
                let (manifest, parity) = nodes[3]
                    .lock()
                    .unwrap()
                    .encode_delegated_coding(&pending.plan, vec![Some(bytes.clone())])
                    .unwrap();
                nodes[1]
                    .lock()
                    .unwrap()
                    .write_coding_parity_range(
                        &pending.plan,
                        &manifest,
                        1,
                        0,
                        &parity[0][..MERKLE_LEAF_SIZE],
                    )
                    .unwrap();
                // The remote queue has acknowledged the plan; no coding worker
                // has run there, so no result or failure can already exist.
                assert!(
                    nodes[3]
                        .lock()
                        .unwrap()
                        .claim_delegated_coding()
                        .unwrap()
                        .is_some()
                );
            }
            if matches!(
                replanning,
                RetryReplanningCase::ExpiredCompleted | RetryReplanningCase::ExpiredDispatched
            ) {
                clients[3].shutdown().await.unwrap();
                network_tasks.remove(3).await.unwrap().unwrap();
            }
            if replanning != RetryReplanningCase::ExpiredDispatched {
                assert!(
                    !dispatch_next_coding_launch(nodes[0].clone(), &clients[0])
                        .await
                        .unwrap()
                );
            } else {
                let deadline = pending.plan.value.expires_at_unix_seconds;
                tokio::time::sleep(Duration::from_secs(
                    deadline.saturating_sub(unix_seconds()) + 1,
                ))
                .await;
                let volume = temp.path().join("volume-0");
                std::fs::rename(&volume, temp.path().join("offline-volume-0")).unwrap();
                nodes[0]
                    .lock()
                    .unwrap()
                    .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                    .unwrap();
                assert!(
                    dispatch_next_coding_launch(nodes[0].clone(), &clients[0])
                        .await
                        .unwrap()
                );
                early_expired_handoff = true;
            }
            let deferred = nodes[0]
                .lock()
                .unwrap()
                .claim_coding_launch()
                .unwrap()
                .unwrap();
            if early_expired_handoff {
                let successor = nodes[0]
                    .lock()
                    .unwrap()
                    .coding_launch_successor_for_test(pending.plan.value.attempt_id)
                    .unwrap()
                    .unwrap();
                assert_eq!(deferred.plan, successor);
                assert!(!deferred.dispatched);
                assert!(deferred.error.is_none());
            } else {
                assert_eq!(deferred.plan, pending.plan);
            }
            assert!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .coding_launch_information_to_stage(deferred.plan.value.attempt_id)
                    .unwrap()
                    .is_some()
            );
            if matches!(
                replanning,
                RetryReplanningCase::ExpiredCompleted | RetryReplanningCase::ExpiredDispatched
            ) {
                if !early_expired_handoff {
                    assert!(!deferred.dispatched);
                    assert!(deferred.error.is_some());
                }
                assert_eq!(
                    nodes[0]
                        .lock()
                        .unwrap()
                        .coding_staged_receipt_count_for_test()
                        .unwrap(),
                    1
                );
            } else {
                assert!(
                    deferred
                        .error
                        .unwrap()
                        .contains("information placement deferred")
                );
            }
            if matches!(
                replanning,
                RetryReplanningCase::ExpiredPartial | RetryReplanningCase::ExpiredFinalized
            ) {
                tokio::time::sleep(Duration::from_secs(4)).await;
                // Expiry can hand off to a fresh attempt while the offline
                // volume's deletion remains a durable holder obligation.
                assert!(
                    dispatch_next_coding_launch(nodes[0].clone(), &clients[0])
                        .await
                        .unwrap()
                );
                early_expired_handoff = true;
                let node = nodes[0].lock().unwrap();
                assert_eq!(
                    node.retired_coding_plan_for_test(pending.plan.value.attempt_id)
                        .unwrap(),
                    Some(pending.plan.clone())
                );
                let successor = node
                    .coding_launch_successor_for_test(pending.plan.value.attempt_id)
                    .unwrap()
                    .unwrap();
                assert_eq!(node.claim_coding_launch().unwrap().unwrap().plan, successor);
                assert!(node.coding_holder_cleanup_count_for_test().unwrap() > 0);
                assert!(
                    node.coding_launch_information_to_stage(successor.value.attempt_id)
                        .unwrap()
                        .is_some()
                );
            }
        }
        for (index, client) in clients.iter().enumerate() {
            if !matches!(
                replanning,
                RetryReplanningCase::ExpiredCompleted | RetryReplanningCase::ExpiredDispatched
            ) || index != 3
            {
                client.shutdown().await.unwrap();
            }
        }
        for task in network_tasks.drain(..) {
            task.await.unwrap().unwrap();
        }
        clients.clear();
        drop(nodes);
        if matches!(
            replanning,
            RetryReplanningCase::StagingRestart
                | RetryReplanningCase::ExpiredPartial
                | RetryReplanningCase::ExpiredFinalized
                | RetryReplanningCase::ExpiredDispatched
        ) {
            std::fs::rename(
                temp.path().join("offline-volume-0"),
                temp.path().join("volume-0"),
            )
            .unwrap();
        }
        if !three_members
            && !stale_epoch
            && !matches!(
                replanning,
                RetryReplanningCase::Live
                    | RetryReplanningCase::VerifiedEpochChange
                    | RetryReplanningCase::VerifiedExpiry
            )
        {
            tokio::time::sleep(Duration::from_secs(4)).await;
        }
        if retired_evidence.is_some() {
            std::fs::rename(
                temp.path().join("offline-volume-1"),
                temp.path().join("volume-1"),
            )
            .unwrap();
        }
        nodes = open_nodes();
        if retired_evidence.is_some() {
            // Reapply the daemon's storage configuration after the previously
            // offline volume returns; opening its database alone does not
            // change the durable admission state from Offline to Online.
            nodes[1]
                .lock()
                .unwrap()
                .configure_storage_volumes(&[temp.path().join("volume-1")], 4 * 1024 * 1024, 0)
                .unwrap();
        }
        if matches!(
            replanning,
            RetryReplanningCase::StagingRestart
                | RetryReplanningCase::ExpiredPartial
                | RetryReplanningCase::ExpiredFinalized
                | RetryReplanningCase::ExpiredCompleted
                | RetryReplanningCase::ExpiredDispatched
        ) {
            let mut node = nodes[0].lock().unwrap();
            node.configure_storage_volumes(&[temp.path().join("volume-0")], 4 * 1024 * 1024, 0)
                .unwrap();
            let pending = node.claim_coding_launch().unwrap().unwrap();
            if early_expired_handoff {
                assert_eq!(
                    Some(pending.plan.clone()),
                    node.coding_launch_successor_for_test(
                        expired_launch.as_ref().unwrap().value.attempt_id
                    )
                    .unwrap()
                );
                assert!(node.coding_holder_cleanup_count_for_test().unwrap() > 0);
            }
            assert!(
                node.coding_launch_information_to_stage(pending.plan.value.attempt_id)
                    .unwrap()
                    .is_some()
            );
            assert_eq!(
                node.coding_reservation_count_for_test().unwrap(),
                if matches!(
                    replanning,
                    RetryReplanningCase::ExpiredFinalized
                        | RetryReplanningCase::ExpiredCompleted
                        | RetryReplanningCase::ExpiredDispatched
                ) {
                    0
                } else {
                    1
                }
            );
        }
        assert_eq!(
            nodes[0]
                .lock()
                .unwrap()
                .coding_retry_evidence_for_test(old.value.attempt_id)
                .unwrap(),
            old_job
        );
        let mut coding_tasks = Vec::new();
        for node in &nodes {
            let mut cfg = config(node.lock().unwrap().keys().node_id());
            cfg.enable_relay_server = false;
            let (client, event_loop) = build_p2p(node.clone(), cfg).unwrap();
            clients.push(client);
            network_tasks.push(tokio::spawn(event_loop.run()));
        }
        let reopened_addresses =
            futures::future::join_all(clients.iter().map(listening_address)).await;
        let reopened_peers = nodes
            .iter()
            .enumerate()
            .map(|(index, node)| {
                let member = certificate
                    .genesis
                    .members
                    .iter()
                    .find(|member| member.node_id == node.lock().unwrap().keys().node_id())
                    .unwrap()
                    .clone();
                GuildPeer {
                    member,
                    endpoints: vec![peer_endpoint(
                        &clients[index],
                        reopened_addresses[index].clone(),
                    )],
                }
            })
            .collect::<Vec<_>>();
        for node in &nodes {
            node.lock()
                .unwrap()
                .install_guild_genesis(certificate.clone(), reopened_peers.clone())
                .unwrap();
        }
        if replanning == RetryReplanningCase::ExpiredDispatched {
            clients[3].shutdown().await.unwrap();
        }
        for (index, client) in clients.iter().enumerate().take(active_count) {
            if replanning == RetryReplanningCase::ExpiredDispatched && index == 3 {
                continue;
            }
            for (remote, node) in nodes.iter().enumerate().take(active_count) {
                if replanning == RetryReplanningCase::ExpiredDispatched && remote == 3 {
                    continue;
                }
                if remote != index {
                    let id = node.lock().unwrap().keys().node_id();
                    client
                        .add_peer_address(id, reopened_addresses[remote].clone())
                        .await
                        .unwrap();
                    client.profile(id).await.unwrap();
                }
            }
        }
        if early_expired_handoff || retired_evidence.is_some() {
            let mut cursor = None;
            for _ in 0..active_count {
                if nodes[0]
                    .lock()
                    .unwrap()
                    .coding_holder_cleanup_count_for_test()
                    .unwrap()
                    == 0
                {
                    break;
                }
                process_coding_holder_cleanup_job(nodes[0].clone(), &clients[0], &mut cursor)
                    .await
                    .unwrap();
            }
            assert_eq!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .coding_holder_cleanup_count_for_test()
                    .unwrap(),
                0
            );
        }
        if let Some(retired) = &retired_evidence {
            // Reopened Submitting state must finish only after the exact fence
            // is confirmed and all active holders acknowledge resumed cleanup.
            for _ in 0..2 {
                process_delegated_coding_job(nodes[3].clone(), &clients[3])
                    .await
                    .unwrap();
            }
            assert!(
                nodes[3]
                    .lock()
                    .unwrap()
                    .claim_delegated_coding()
                    .unwrap()
                    .is_none()
            );
            assert_eq!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .retired_coding_plan_for_test(
                        extra_stale_plan.as_ref().unwrap().value.attempt_id
                    )
                    .unwrap(),
                extra_stale_plan
            );
            assert_eq!(
                nodes[0]
                    .lock()
                    .unwrap()
                    .retired_coding_plan_for_test(retired.value.plan.value.attempt_id)
                    .unwrap(),
                Some(retired.value.plan.clone())
            );
            assert!(
                submit_delegated_coding_result(nodes[3].clone(), &clients[3], retired.clone())
                    .await
                    .is_err()
            );
            // The retired launch already handed off before reopen. A single
            // dispatch pass may defer its successor while holder cleanup is
            // still outstanding; the queued lane below must retain progress.
            dispatch_next_coding_launch(nodes[0].clone(), &clients[0])
                .await
                .unwrap();
        }
        if cleanup_race != Some(CodingCleanupRace::Failure)
            && !matches!(
                replanning,
                RetryReplanningCase::None | RetryReplanningCase::ExpiredDispatched
            )
        {
            let peers = nodes[0]
                .lock()
                .unwrap()
                .guild_summary()
                .unwrap()
                .unwrap()
                .peers;
            queue_variable_coding_lanes(
                nodes[0].clone(),
                &clients[0],
                owner,
                replacement.checkpoint_hash,
                replacement.membership_epoch,
                &peers,
                vec![production_lane()],
            )
            .await
            .unwrap();
            if retired_evidence.is_none()
                && matches!(
                    replanning,
                    RetryReplanningCase::Live
                        | RetryReplanningCase::VerifiedEpochChange
                        | RetryReplanningCase::VerifiedExpiry
                )
            {
                let node = nodes[0].lock().unwrap();
                if matches!(
                    replanning,
                    RetryReplanningCase::VerifiedEpochChange | RetryReplanningCase::VerifiedExpiry
                ) {
                    if cleanup_race == Some(CodingCleanupRace::Launch) {
                        assert!(node.claim_coding_launch().unwrap().is_none());
                    } else {
                        let pending = node.claim_coding_launch().unwrap().unwrap();
                        assert!(pending.dispatched);
                        assert_eq!(pending.plan, accepted_evidence.as_ref().unwrap().value.plan);
                    }
                } else {
                    assert!(node.claim_coding_launch().unwrap().is_none());
                }
                assert_eq!(node.coding_staged_receipt_count_for_test().unwrap(), 0);
                assert_eq!(node.coding_reservation_count_for_test().unwrap(), 0);
                assert_eq!(node.coding_used_bytes_for_test().unwrap(), 0);
            }
            if let Some(retired) = &retired_evidence {
                let node = nodes[0].lock().unwrap();
                let job = node
                    .claim_coding_launch()
                    .unwrap()
                    .expect("retired lane must enqueue fresh work");
                assert_ne!(
                    job.plan.value.attempt_id,
                    retired.value.plan.value.attempt_id
                );
                assert_eq!(
                    job.plan.value.membership_epoch,
                    node.dynamic_guild_state()
                        .unwrap()
                        .unwrap()
                        .membership_epoch
                );
                assert_eq!(job.plan.value.format_version, 3);
            }
        } else if queue_replacement && replanning != RetryReplanningCase::ExpiredDispatched {
            let replacement = nodes[0]
                .lock()
                .unwrap()
                .sign_coding_attempt_plan(replacement.clone())
                .unwrap();
            nodes[0]
                .lock()
                .unwrap()
                .enqueue_coding_launch(replacement)
                .unwrap();
        }
        let unrelated_group = if cleanup_race == Some(CodingCleanupRace::Failure) {
            let current = nodes[0]
                .lock()
                .unwrap()
                .dynamic_guild_state()
                .unwrap()
                .unwrap();
            let member = |index: usize| {
                current
                    .active_members()
                    .find(|member| member.node_id == nodes[index].lock().unwrap().keys().node_id())
                    .unwrap()
                    .clone()
            };
            let info_owner = member(2);
            let info_id = mb_core::make_sector_id(
                info_owner.node_id,
                Uuid::from_bytes([247; 16]),
                mb_core::SectorPurpose::Metadata,
                0,
            );
            let (info_ref, info_bytes) = mb_core::encrypted_sector(
                &nodes[2].lock().unwrap().keys().guild_data_key(&guild_id),
                info_id,
                &[91],
            )
            .unwrap();
            nodes[2]
                .lock()
                .unwrap()
                .install_repaired_information_sector(guild_id, info_ref.clone(), &info_bytes)
                .unwrap();
            let mut value = replacement.clone();
            value.attempt_id = [247; 16];
            value.checkpoint_hash = [246; 32];
            value.expires_at_unix_seconds = unix_seconds() + 600;
            value.geometry.information[0].owner = info_owner.node_id;
            value.geometry.information[0].failure_domain = info_owner.failure_domain;
            value.geometry.information[0].sector.id = info_id;
            value.geometry.information[0].sector.commitment = merkle_commit(&info_bytes).unwrap();
            value.geometry.information[0].sector.logical_len = info_ref.logical_len;
            value.information_roots = Some(vec![info_ref.root]);
            value.geometry.parity[0].holder = member(4).node_id;
            value.geometry.parity[0].failure_domain = member(4).failure_domain;
            value.coding_coordinator = member(2).node_id;
            value.verification_coordinator = member(4).node_id;
            let plan = {
                let mut node = nodes[0].lock().unwrap();
                let plan = node.sign_coding_attempt_plan(value).unwrap();
                node.enqueue_coding_launch(plan.clone()).unwrap();
                plan
            };
            let (manifest, _) = nodes[2]
                .lock()
                .unwrap()
                .encode_delegated_coding(&plan, vec![Some(info_bytes)])
                .unwrap();
            Some(manifest.value.group.id)
        } else {
            None
        };
        for (index, node) in nodes.iter().enumerate().take(active_count) {
            if replanning == RetryReplanningCase::ExpiredDispatched && index == 3 {
                continue;
            }
            coding_tasks.push(tokio::spawn(run_delegated_coding_jobs(
                node.clone(),
                clients[index].clone(),
            )));
        }
        // Quorum collection and event dissemination each wait through a
        // logical request deadline for the intentionally offline member.
        let timeout = if replanning == RetryReplanningCase::ExpiredDispatched {
            240
        } else {
            60
        };
        let deadline = tokio::time::Instant::now() + Duration::from_secs(timeout);
        let mut observed_coding_errors = BTreeSet::new();
        loop {
            if retired_evidence.is_some() {
                for node in &nodes {
                    let node = node.lock().unwrap();
                    for job in node.delegated_coding_jobs_for_test().unwrap() {
                        if let Some(error) = job.error {
                            observed_coding_errors.insert(error);
                        }
                    }
                }
            }
            let complete = {
                let node = nodes[0].lock().unwrap();
                node.validate_variable_checkpoint_coverage(&checkpoint, false)
                    .is_ok()
                    && unrelated_group.is_none_or(|group_id| {
                        node.dynamic_guild_state()
                            .unwrap()
                            .unwrap()
                            .coding_groups
                            .iter()
                            .any(|retained| retained.group.id == group_id)
                    })
                    && node
                        .coding_activation_jobs_for_test()
                        .unwrap()
                        .iter()
                        .all(|job| job.complete)
            };
            if complete {
                break;
            }
            if tokio::time::Instant::now() >= deadline {
                let jobs = nodes
                    .iter()
                    .map(|node| {
                        let node = node.lock().unwrap();
                        let launches = node
                            .coding_launch_jobs_for_test()
                            .unwrap()
                            .into_iter()
                            .map(|job| {
                                (
                                    hex::encode(job.plan.value.attempt_id),
                                    job.plan.value.membership_epoch,
                                    job.dispatched,
                                    job.error,
                                )
                            })
                            .collect::<Vec<_>>();
                        let delegated = node
                            .delegated_coding_jobs_for_test()
                            .unwrap()
                            .into_iter()
                            .map(|job| {
                                (hex::encode(job.plan.value.attempt_id), job.state, job.error)
                            })
                            .collect::<Vec<_>>();
                        (launches, delegated)
                    })
                    .collect::<Vec<_>>();
                let node = nodes[0].lock().unwrap();
                let launch = node
                    .claim_coding_launch()
                    .unwrap()
                    .map(|job| (job.dispatched, job.error));
                let retry = node.claim_coding_retry(None).unwrap().map(|job| job.error);
                let coverage = node
                    .validate_variable_checkpoint_coverage(&checkpoint, false)
                    .err();
                let activations = node
                    .coding_activation_jobs_for_test()
                    .unwrap()
                    .into_iter()
                    .map(|job| (job.complete, job.error))
                    .collect::<Vec<_>>();
                panic!(
                    "coding worker did not finish checkpoint coverage; workers finished={:?}; jobs={:?}; observed errors={:?}; launch={:?}; retry={:?}; activation={:?}; coverage={:?}",
                    coding_tasks
                        .iter()
                        .map(tokio::task::JoinHandle::is_finished)
                        .collect::<Vec<_>>(),
                    jobs,
                    observed_coding_errors,
                    launch,
                    retry,
                    activations,
                    coverage
                );
            }
            tokio::time::sleep(Duration::from_millis(100)).await;
        }
        assert!(
            coding_tasks.iter().all(|task| !task.is_finished()),
            "coding workers must stay alive through ownership transfer"
        );
        if let Some(blocked) = &blocked_launch {
            {
                let mut node = nodes[0].lock().unwrap();
                node.sign_checkpoint(&checkpoint).unwrap();
                let pending = node.claim_coding_launch().unwrap().unwrap();
                assert_eq!(pending.plan, *blocked);
                assert!(
                    pending
                        .error
                        .unwrap()
                        .contains("information placement deferred")
                );
                assert!(
                    node.coding_launch_information_to_stage(blocked.value.attempt_id)
                        .unwrap()
                        .is_some()
                );
            }
            let volume = temp.path().join("volume-2");
            std::fs::rename(temp.path().join("offline-volume-2"), &volume).unwrap();
            nodes[2]
                .lock()
                .unwrap()
                .configure_storage_volumes(&[volume], 4 * 1024 * 1024, 0)
                .unwrap();
            let deadline = tokio::time::Instant::now() + Duration::from_secs(60);
            loop {
                let complete = {
                    let node = nodes[0].lock().unwrap();
                    node.claim_coding_launch().unwrap().is_none() && node.claim_coding_activation().unwrap().is_none()
                        && node.dynamic_guild_state().unwrap().unwrap().coding_groups.iter().any(|retained|
                            retained.group.roles.iter().any(|role| matches!(role, ShardRoleV2::Information(info) if info.owner == blocked.value.geometry.information[0].owner)))
                };
                if complete {
                    break;
                }
                assert!(
                    tokio::time::Instant::now() < deadline,
                    "restored blocked launch did not activate"
                );
                tokio::time::sleep(Duration::from_millis(100)).await;
            }
        }
        {
            let mut node = nodes[0].lock().unwrap();
            if state.membership_epoch != 1 {
                let current = node.dynamic_guild_state().unwrap().unwrap();
                checkpoint.format_version = 5;
                checkpoint.authority = Some(CheckpointAuthority {
                    format_version: 1,
                    membership_epoch: current.membership_epoch,
                    quorum: current.quorum,
                });
            }
            node.sign_checkpoint(&checkpoint).unwrap();
            if let Some(expired) = &expired_launch {
                assert_eq!(
                    node.retired_coding_plan_for_test(expired.value.attempt_id)
                        .unwrap(),
                    Some(expired.clone())
                );
                let successor = node
                    .coding_launch_successor_for_test(expired.value.attempt_id)
                    .unwrap()
                    .unwrap();
                assert_ne!(successor.value.attempt_id, expired.value.attempt_id);
                assert!(successor.value.expires_at_unix_seconds > unix_seconds());
                if replanning == RetryReplanningCase::ExpiredDispatched {
                    for candidate in [
                        successor.value.coding_coordinator,
                        successor.value.verification_coordinator,
                    ] {
                        assert_ne!(candidate, expired.value.coding_coordinator);
                        assert_ne!(candidate, expired.value.verification_coordinator);
                    }
                }
                let current = node.dynamic_guild_state().unwrap().unwrap();
                let retained = current
                    .coding_groups
                    .iter()
                    .find(|retained| retained.retired_at_event.is_none())
                    .unwrap();
                assert_eq!(
                    node.coding_transcript_for_group(guild_id, retained.group.id)
                        .unwrap()
                        .value
                        .plan,
                    successor
                );
                assert!(
                    node.coding_launch_information_to_stage(expired.value.attempt_id)
                        .unwrap()
                        .is_none()
                );
                assert!(
                    node.coding_launch_information_to_stage(successor.value.attempt_id)
                        .unwrap()
                        .is_none()
                );
            }
            if let Some(expected) = &accepted_evidence {
                assert_eq!(
                    node.coding_transcript_for_group(
                        guild_id,
                        expected.value.manifest.value.group.id
                    )
                    .unwrap(),
                    *expected
                );
            }
            let evidence = node
                .coding_retry_evidence_for_test(old.value.attempt_id)
                .unwrap();
            assert_eq!(evidence.failure, old_job.failure);
            if three_members {
                assert!(!evidence.complete);
                assert!(
                    evidence
                        .error
                        .unwrap()
                        .contains("fewer than two fresh reachable coordinators")
                );
            } else {
                assert!(evidence.complete);
                if replanning != RetryReplanningCase::None {
                    if matches!(
                        replanning,
                        RetryReplanningCase::StagingRestart
                            | RetryReplanningCase::ExpiredPartial
                            | RetryReplanningCase::ExpiredFinalized
                            | RetryReplanningCase::ExpiredCompleted
                            | RetryReplanningCase::ExpiredDispatched
                            | RetryReplanningCase::LaunchFairness
                    ) {
                        assert_eq!(evidence.retry_plan, old_job.retry_plan);
                    } else {
                        assert_eq!(evidence, old_job);
                    }
                    if let Some(child) = &child_job {
                        let retained = node
                            .coding_retry_evidence_for_test(
                                child.failure.value.plan.value.attempt_id,
                            )
                            .unwrap();
                        assert!(retained.complete);
                        assert_eq!(retained.failure, child.failure);
                        assert_eq!(retained.retry_plan, child.retry_plan);
                    }
                } else if queue_replacement {
                    assert_eq!(evidence.retry_plan, expired_plan);
                } else {
                    let renewed = evidence.retry_plan.as_ref().unwrap();
                    assert_eq!(renewed.value.format_version, 3);
                    assert_ne!(
                        renewed.value.attempt_id,
                        expired_plan.as_ref().unwrap().value.attempt_id
                    );
                    assert_ne!(
                        renewed.value.coding_coordinator,
                        expired_plan.as_ref().unwrap().value.coding_coordinator
                    );
                    assert_ne!(
                        renewed.value.verification_coordinator,
                        expired_plan
                            .as_ref()
                            .unwrap()
                            .value
                            .verification_coordinator
                    );
                    assert_eq!(
                        node.coding_retry_previous_plan(&evidence).unwrap(),
                        expired_plan.unwrap()
                    );
                    let initial = node.sign_coding_attempt_plan(replacement.clone()).unwrap();
                    assert_eq!(node.enqueue_coding_launch(initial).unwrap(), *renewed);
                }
            }
        }
        assert_eq!(
            nodes[1]
                .lock()
                .unwrap()
                .coding_reservation_count_for_test()
                .unwrap(),
            0
        );
        if replanning != RetryReplanningCase::None {
            for (index, node) in nodes.iter().enumerate() {
                let node = node.lock().unwrap();
                assert_eq!(node.coding_reservation_count_for_test().unwrap(), 0);
                assert_eq!(node.coding_staged_receipt_count_for_test().unwrap(), 0);
                assert_eq!(
                    node.coding_used_bytes_for_test().unwrap(),
                    if index == 1
                        || unrelated_group.is_some() && index == 4
                        || index == 0 && matches!(cleanup_race, Some(CodingCleanupRace::Retired))
                        || replanning == RetryReplanningCase::LaunchFairness
                            && matches!(index, 2 | 4)
                        || index == 0
                            && !matches!(
                                replanning,
                                RetryReplanningCase::Live
                                    | RetryReplanningCase::VerifiedEpochChange
                                    | RetryReplanningCase::VerifiedExpiry
                            )
                    {
                        V1_SECTOR_SIZE as u64
                    } else {
                        0
                    }
                );
            }
        }
        for task in coding_tasks {
            task.abort();
            let _ = task.await;
        }
        for (index, client) in clients.iter().enumerate() {
            if replanning != RetryReplanningCase::ExpiredDispatched || index != 3 {
                client.shutdown().await.unwrap();
            }
        }
        for task in network_tasks {
            task.await.unwrap().unwrap();
        }
        drop(clients);
        drop(nodes);
        for _ in 0..2 {
            for (index, seed) in seeds.iter().enumerate() {
                if index != 0 && replanning == RetryReplanningCase::None {
                    continue;
                }
                let node =
                    Node::open(temp.path().join(format!("node-{index}")), seed.clone()).unwrap();
                if index == 0 {
                    if early_expired_handoff || retired_evidence.is_some() {
                        assert_eq!(node.coding_holder_cleanup_count_for_test().unwrap(), 0);
                    }
                    if let Some(group_id) = unrelated_group {
                        assert!(
                            node.dynamic_guild_state()
                                .unwrap()
                                .unwrap()
                                .coding_groups
                                .iter()
                                .any(|retained| retained.group.id == group_id)
                        );
                        node.coding_transcript_for_group(guild_id, group_id)
                            .unwrap();
                    }
                    if let Some(transcript) = &failed_evidence {
                        assert!(
                            node.accept_coding_transcript(
                                transcript.value.plan.value.coding_coordinator,
                                transcript.clone(),
                            )
                            .is_err()
                        );
                    }
                    if let Some(failure) = &delayed_failure {
                        let retry = node
                            .coding_retry_evidence_for_test(failure.value.plan.value.attempt_id)
                            .unwrap();
                        assert_eq!(retry.failure, *failure);
                        assert!(retry.complete);
                        let successor = retry.retry_plan.unwrap();
                        assert_ne!(
                            successor.value.attempt_id,
                            failure.value.plan.value.attempt_id
                        );
                        assert_ne!(
                            successor.value.coding_coordinator,
                            failure.value.plan.value.coding_coordinator
                        );
                        assert_ne!(
                            successor.value.verification_coordinator,
                            failure.value.plan.value.verification_coordinator
                        );
                    }
                    if let Some(retired) = &retired_evidence {
                        assert_eq!(
                            node.retired_coding_plan_for_test(retired.value.plan.value.attempt_id)
                                .unwrap(),
                            Some(retired.value.plan.clone())
                        );
                        let current = node.dynamic_guild_state().unwrap().unwrap();
                        let group = current
                            .coding_groups
                            .iter()
                            .find(|retained| retained.retired_at_event.is_none())
                            .unwrap();
                        let transcript = node
                            .coding_transcript_for_group(guild_id, group.group.id)
                            .unwrap();
                        assert_ne!(
                            transcript.value.plan.value.attempt_id,
                            retired.value.plan.value.attempt_id
                        );
                        assert_eq!(
                            transcript.value.plan.value.membership_epoch,
                            current.membership_epoch
                        );
                    }
                    if let Some(expired) = &expired_launch {
                        assert_eq!(
                            node.retired_coding_plan_for_test(expired.value.attempt_id)
                                .unwrap(),
                            Some(expired.clone())
                        );
                        let successor = node
                            .coding_launch_successor_for_test(expired.value.attempt_id)
                            .unwrap()
                            .unwrap();
                        let current = node.dynamic_guild_state().unwrap().unwrap();
                        let retained = current
                            .coding_groups
                            .iter()
                            .find(|retained| retained.retired_at_event.is_none())
                            .unwrap();
                        assert_eq!(
                            node.coding_transcript_for_group(guild_id, retained.group.id)
                                .unwrap()
                                .value
                                .plan,
                            successor
                        );
                        assert!(
                            node.coding_launch_information_to_stage(expired.value.attempt_id)
                                .unwrap()
                                .is_none()
                        );
                        assert!(
                            node.coding_launch_information_to_stage(successor.value.attempt_id)
                                .unwrap()
                                .is_none()
                        );
                    }
                    if let Some(expected) = &accepted_evidence {
                        assert_eq!(
                            node.coding_transcript_for_group(
                                guild_id,
                                expected.value.manifest.value.group.id
                            )
                            .unwrap(),
                            *expected
                        );
                    }
                    node.validate_variable_checkpoint_coverage(&checkpoint, false)
                        .unwrap();
                    assert_eq!(
                        node.claim_coding_retry(None).unwrap().is_some(),
                        three_members
                    );
                    assert!(node.claim_coding_launch().unwrap().is_none());
                    assert!(node.claim_coding_activation().unwrap().is_none());
                    let initial_id = CodingAttemptPlan::initial_attempt_id_at_membership(
                        3,
                        replacement.checkpoint_hash,
                        replacement.membership_epoch,
                        &replacement.geometry,
                        replacement.information_roots.as_ref().unwrap(),
                    )
                    .unwrap();
                    assert!(
                        node.coding_launch_information_to_stage(initial_id)
                            .unwrap()
                            .is_none()
                    );
                }
                if replanning != RetryReplanningCase::None {
                    assert_eq!(node.coding_reservation_count_for_test().unwrap(), 0);
                    assert_eq!(node.coding_staged_receipt_count_for_test().unwrap(), 0);
                    assert_eq!(
                        node.coding_used_bytes_for_test().unwrap(),
                        if index == 1
                            || unrelated_group.is_some() && index == 4
                            || index == 0
                                && matches!(cleanup_race, Some(CodingCleanupRace::Retired))
                            || replanning == RetryReplanningCase::LaunchFairness
                                && matches!(index, 2 | 4)
                            || index == 0
                                && !matches!(
                                    replanning,
                                    RetryReplanningCase::Live
                                        | RetryReplanningCase::VerifiedEpochChange
                                        | RetryReplanningCase::VerifiedExpiry
                                )
                        {
                            V1_SECTOR_SIZE as u64
                        } else {
                            0
                        }
                    );
                }
            }
        }
    }

    #[tokio::test]
    async fn relay_endpoints_for_one_peer_share_one_reservation_lifecycle() {
        let temp = tempfile::tempdir().unwrap();
        let node = Node::open(temp.path().join("member"), Seed::from_bytes([92; 32])).unwrap();
        let node_id = node.keys().node_id();
        let relay_peer = KeyMaterial::from_seed(&Seed::from_bytes([93; 32]))
            .node_id()
            .libp2p_peer_id()
            .unwrap();
        let first: Multiaddr = format!("/ip4/127.0.0.1/udp/41001/quic-v1/p2p/{relay_peer}")
            .parse()
            .unwrap();
        let second: Multiaddr = format!("/ip4/127.0.0.1/udp/41002/quic-v1/p2p/{relay_peer}")
            .parse()
            .unwrap();
        let mut member_config = config(node_id);
        member_config.enable_relay_server = false;
        member_config.relay_reservation_addresses = vec![second.clone(), first.clone()];

        let (_client, mut event_loop) =
            build_p2p(Arc::new(Mutex::new(node)), member_config).unwrap();

        assert_eq!(event_loop.relay_reservations.len(), 1);
        assert_eq!(event_loop.relay_listeners.len(), 1);
        assert_eq!(
            event_loop.persistent_addresses.get(&relay_peer).unwrap(),
            &BTreeSet::from([
                normalize_known_address(relay_peer, first).unwrap(),
                normalize_known_address(relay_peer, second).unwrap(),
            ])
        );

        let initial_listeners = event_loop.relay_listeners.clone();
        event_loop
            .active_relay_listeners
            .extend(initial_listeners.keys().copied());
        for _ in 0..3 {
            event_loop.retry_relay_reservations();
            assert_eq!(event_loop.relay_listeners, initial_listeners);
            assert_eq!(event_loop.active_relay_listeners.len(), 1);
        }
        let relay_endpoints = event_loop
            .current_advertised_endpoints()
            .addresses
            .into_iter()
            .filter(|address| address.contains("/p2p-circuit"))
            .collect::<Vec<_>>();
        assert_eq!(relay_endpoints.len(), 2);
    }

